#[async_trait]
pub trait WatchAndReload {
    type Error;
    async fn watch_and_reload<'a>(&self, tx: Option<mpsc::Sender<Result<(), Self::Error>>>, runner: Arc<dyn CommandRunner + Send + Sync + 'a>, cancel_token: CancellationToken) -> Result<(), Self::Error>;
    async fn is_relevant_change(&self, path: &Path) -> bool;
}

pub async fn handle_path_change<'a,X,E>(watched: &X, path: &Path, tx: Option<&mpsc::Sender<Result<(), E>>>, runner: &Arc<dyn CommandRunner + Send + Sync + 'a>) -> Result<(), E> where
    X: WatchAndReload<Error=E> + RebuildOrTest<Error=E>,
    E: From<WatchError>, {
    if watched.is_relevant_change(path).await {
        info!("Detected relevant change in file: {:?}", path);

        let rebuild_result = watched.rebuild_or_test(runner.as_ref()).await;
        notify_rebuild_result(tx, rebuild_result).await;
    }
    Ok(())
}


pub async fn watch_loop<'a,X,E>(watched: &X, _watcher: &mut RecommendedWatcher, _workspace_path: &PathBuf, notify_rx: async_channel::Receiver<notify::Result<notify::Event>>, tx: Option<mpsc::Sender<Result<(), E>>>, runner: Arc<dyn CommandRunner + Send + Sync + 'a>, cancel_token: CancellationToken) -> Result<(), E> where
    X: WatchAndReload<Error=E> + RebuildOrTest<Error=E>,
    E: From<WatchError>, {
    loop {
        let cancel_clone = cancel_token.clone();
        tokio::select! {
            // 2a) If we get a file event
            event_res = notify_rx.recv() => {
                match event_res {
                    Ok(res) => {
                        process_notify_event(watched, res, tx.as_ref(), &runner).await?;
                    },
                    Err(_closed) => {
                        // channel closed
                        break;
                    }
                }
            },

            // 2b) If we get a cancellation
            _ = cancel_clone.cancelled() => {
                break;
            }
        }
    }
    Ok(())
}


pub fn setup_file_watching(workspace_path: &Path) -> Result<(RecommendedWatcher, async_channel::Receiver<notify::Result<notify::Event>>), WatchError> {
    // We'll use an async channel to push notify events to our async loop
    let (notify_tx, notify_rx) = async_channel::unbounded();

    // Create the `RecommendedWatcher`
    let notify_tx_clone = notify_tx.clone();
    let mut watcher = RecommendedWatcher::new(
        move |res| {
            // This closure is invoked on every filesystem event from notify
            let _ = notify_tx_clone.try_send(res);
        },
        notify::Config::default(),
    )
    .map_err(|e| WatchError::NotifyError(e.into()))?;

    // Start watching
    watcher
        .watch(workspace_path, RecursiveMode::Recursive)
        .map_err(|e| WatchError::NotifyError(e.into()))?;

    Ok((watcher, notify_rx))
}


pub async fn process_notify_event<'a,X,E>(watched: &X, event: Result<notify::Event, notify::Error>, tx: Option<&mpsc::Sender<Result<(), E>>>, runner: &Arc<dyn CommandRunner + Send + Sync + 'a>) -> Result<(), E> where
    X: WatchAndReload<Error=E> + RebuildOrTest<Error=E>,
    E: From<WatchError>, {
    match event {
        Ok(ev) => {
            for path in ev.paths.iter() {
                handle_path_change(watched, path, tx, runner).await?;
            }
        }
        Err(e) => {
            error!("File watch error: {:?}", e);
            let e: Arc<notify::Error> = Arc::new(e);
            let e = WatchError::NotifyError(e);
            if let Some(sender) = tx {
                let _ = sender.send(Err(E::from(e.clone()))).await;
            }
            return Err(E::from(e));
        }
    }
    Ok(())
}


pub async fn notify_rebuild_result<E>(tx: Option<&mpsc::Sender<Result<(), E>>>, rebuild_result: Result<(), E>) where E: From<WatchError>, {
    if let Some(sender) = tx {
        let _ = sender.send(rebuild_result).await;
    }
}

impl WatchAndReload for CrateHandle {
    type Error = CrateError;
    ///
    /// Sets up file-watching for this one crate, then enters a watch loop
    /// until `cancel_token` is triggered. Triggers rebuild/test whenever
    /// a relevant change is detected.
    async fn watch_and_reload<'a>(&self, tx: Option<mpsc::Sender<Result<(), Self::Error>>>, runner: Arc<dyn CommandRunner + Send + Sync + 'a>, cancel_token: CancellationToken) -> Result<(), Self::Error> {
        let crate_path = self.root_dir_path_buf();
        info!("Setting up file watching for crate at: {}", crate_path.display());

        let (mut watcher, notify_rx) = setup_file_watching(&crate_path)?;

        info!("Entering watch loop for crate at: {}", crate_path.display());
        watch_loop(
            self,
            &mut watcher,
            &crate_path,
            notify_rx,
            tx,
            runner,
            cancel_token,
        )
        .await?;

        info!("Watch loop ended gracefully for crate at: {}", crate_path.display());
        Ok(())
    }
    ///
    /// A change is considered “relevant” if it's Cargo.toml or in `src/`
    async fn is_relevant_change(&self, path: &Path) -> bool {
        if path.file_name() == Some(std::ffi::OsStr::new("Cargo.toml")) {
            return true;
        }
        let src_path = self.as_ref().join("src");
        path.starts_with(&src_path)
    }
}

impl<P,H> WatchAndReload for Workspace<P,H> where for<'async_trait> P: From<PathBuf> + AsRef<Path> + Send + Sync + 'async_trait, H: WatchAndReload<Error=CrateError> + RebuildOrTest<Error=CrateError> + CrateHandleInterface<P> + Send + Sync {
    type Error = WorkspaceError;
    async fn watch_and_reload<'a>(&self, tx: Option<mpsc::Sender<Result<(), Self::Error>>>, runner: Arc<dyn CommandRunner + Send + Sync + 'a>, cancel_token: CancellationToken) -> Result<(), Self::Error> {

        trace!("workspace::watch_and_reload invoked");

        let workspace_path = self.root_dir_path_buf();

        trace!("Workspace path is: {}", workspace_path.display());

        let (mut watcher, notify_rx) = setup_file_watching(&workspace_path)
            .map_err(WorkspaceError::from)?;

        debug!("Created file watcher for workspace at: {}", workspace_path.display());

        // 2) Wrap the call to `watch_loop` in a block so that the short-lived borrow of `self`
        //    does not get carried across `.await`. We pass `ws_ref` briefly, then `.await`.
        let result = {
            let ws_ref = self; // ephemeral borrow
            async move {
                watch_loop(
                    ws_ref,
                    &mut watcher,
                    &workspace_path,
                    notify_rx,
                    tx,
                    runner,
                    cancel_token,
                )
                .await
            }
        }
        .await;

        info!("workspace::watch_and_reload finished with result: {:?}", result);
        result
    }
    async fn is_relevant_change(&self, path: &Path) -> bool {
        trace!("Checking if path is relevant in workspace: {:?}", path);

        if path.file_name() == Some(std::ffi::OsStr::new("Cargo.toml")) {
            return true;
        }

        for crate_handle in self.crates() {
            let guard = crate_handle.lock().await;
            let crate_src_path = guard.root_dir_path_buf().join("src");
            if path.starts_with(&crate_src_path) {
                return true;
            }
        }

        false
    }
}

