pub trait ReadmeWritingCrateHandle<P> {}


/// One pragmatic way to address “losing access to the crate or workspace handle”
/// is to store enough information inside each request so that, after the AI
/// expansions finish, you can locate and update the relevant Cargo.toml and README.
/// That can be done in at least two ways:
///
/// 1) **Store the path(s) or crate handle directly in the request**:
///    - e.g. each `AiReadmeWriterRequest` has an `Arc<CrateHandle>` or a `PathBuf`
///      pointing to the crate directory. Then, after expansions, you can
///      `for (req, response) in writer.gather_results(...)` => `req.update_files(response)`.
/// 2) **Use a separate trait + “registry”**:
///    - e.g. keep a global or external map from `crate_name` → `CrateHandle`.
///    - Inside your loop, you find the matching handle: `let crate_handle = handle_map[req.crate_name()]`,
///      then call `crate_handle.update_files(response)`.
/// Either way, you can define a trait “ApplyAiReadmeOutput” that has methods for rewriting
/// README.md & Cargo.toml. For example:
/// ```rust
#[async_trait]
pub trait ApplyAiReadmeOutput {
    type Error;
    async fn update_readme_md(&self, new_contents: &str) -> Result<(), Self::Error>;
    async fn update_cargo_toml(&self, new_description: &str, new_keywords: &[String], new_categories: &[String]) -> Result<(), Self::Error>;
}


#[async_trait]
pub trait UpdateReadmeFiles {
    type Error;
    async fn update_readme_files(handle: Arc<AsyncMutex<Self>>) -> Result<(), Self::Error>;
}

/// This structure is a directive indicating which fields we need you to provide for us in your response to our query.
///
#[derive(AiJsonTemplate,SaveLoad,Builder,Getters,Debug,Clone,Serialize,Deserialize)]
#[getset(get="pub")]
#[builder(setter(into))]
pub struct AiReadmeWriterDesiredOutput {
    crate_name: String,
    full_readme_markdown: String,
    package_description: String,
    package_keywords: Vec<String>,
    package_categories: Vec<String>,
}


#[derive(Serialize,Deserialize,Debug,Builder,Getters,Clone)]
#[builder(setter(into))]
#[getset(get = "pub")]
pub struct AiReadmeWriterRequest<P> where
    P: AsRef<Path> + Send + Sync + 'static, {
    crate_handle: Arc<AsyncMutex<dyn ReadmeWritingCrateHandle<P>>>,
    crate_name: String,
    version: semver::Version,
    consolidated_crate_interface: ConsolidatedCrateInterface,
    maybe_cargo_toml_package_authors: Option<Vec<String>>,
    maybe_cargo_toml_rust_edition: Option<String>,
    maybe_cargo_toml_license: Option<String>,
    maybe_cargo_toml_crate_repository_location: Option<String>,
}


#[derive(Builder,Getters,LanguageModelBatchWorkflow)]
#[builder(setter(into))]
#[getset(get = "pub")]
#[batch_error_type(LanguageModelBatchWorkflowError)]
#[batch_json_output_format(AiReadmeWriterDesiredOutput)]
pub struct AiReadmeWriter {
    language_model_client: LanguageModelClientArc,
    language_model_type: LanguageModelType,
    batch_workspace: Arc<BatchWorkspace>,
}

pub async fn execute_ai_readme_writer_requests(writer: &mut AiReadmeWriter, requests: &[AiReadmeWriterRequest<PathBuf>]) -> Result<(), AiReadmeWriterError> {
    let unseen = writer.batch_workspace().calculate_unseen_inputs(&requests,&ExpectedContentType::Json);

    writer.plant_seed_and_wait(&unseen).await?;

    info!("Gathering AI expansions from the workspace.");
    let results = writer.gather_results(&unseen).await?;

    debug!("Gathered results={:#?}",results);
    for (request, response) in results {
        // Because request.crate_handle() => Arc<dyn ReadmeWritingCrateHandle<P>>
        // that has .update_readme_md + .update_cargo_toml
        let handle = request.crate_handle();
        let guard = handle.lock().await;
        guard.update_readme_md(response.full_readme_markdown()).await?;
        guard.update_cargo_toml(
            response.package_description(),
            response.package_keywords(),
            response.package_categories(),
        ).await?;
    }

    info!("Successfully completed execute_ai_readme_writer_requests.");
    Ok(())
}

impl Named for AiReadmeWriterDesiredOutput {
    fn name(&self) -> std::borrow::Cow<'_, str> {
        std::borrow::Cow::Owned(format!("{}-ai-generated-readme", self.crate_name()))
    }
}

impl<P> AiReadmeWriterRequest<P> where P: AsRef<Path> + Send + Sync + 'static {
    pub async fn async_try_from<H>(handle: Arc<AsyncMutex<H>>) -> Result<Self, AiReadmeWriterError> where
            H: ReadmeWritingCrateHandle<P>, {
        use std::ops::Deref;

        // 2) We'll store it as Arc<dyn ReadmeWritingCrateHandle<P>>.
        let crate_handle_obj: Arc<AsyncMutex<dyn ReadmeWritingCrateHandle<P>>> = handle.clone();

        let guard = handle.lock().await;

        let consolidation_opts = ConsolidationOptions::new().with_docs().with_fn_bodies();

        // 1) We can call name(), version(), etc. because H: CrateHandleInterface<P>.
        let crate_name = guard.name().to_string();
        let version = guard
            .version()
            .expect("expected a valid version in the crate");

        let consolidated_crate_interface = guard
            .consolidate_crate_interface(&consolidation_opts)
            .await?;

        // 3) Now we do a short synchronous read from CargoToml (like get_package_authors),
        //    but we must not hold any lock across await, so keep it “direct.”
        let direct_authors = {
            let cargo_toml = guard.cargo_toml();
            let mut guard = cargo_toml.lock().await;
            guard.get_package_authors()?
        };
        let maybe_cargo_toml_package_authors = if direct_authors.is_some() {
            direct_authors
        } else {
            // do fallback or None
            None
        };

        let direct_edition = {
            let cargo_toml = guard.cargo_toml();
            let mut guard = cargo_toml.lock().await;
            guard.get_rust_edition()?
        };
        let maybe_cargo_toml_rust_edition = if direct_edition.is_some() {
            direct_edition
        } else {
            None
        };

        let direct_license = {
            let cargo_toml = guard.cargo_toml();
            let mut guard = cargo_toml.lock().await;
            guard.get_license_type()?
        };
        let maybe_cargo_toml_license = if direct_license.is_some() {
            direct_license
        } else {
            None
        };

        let direct_repo = {
            let cargo_toml = guard.cargo_toml();
            let mut guard = cargo_toml.lock().await;
            guard.get_crate_repository_location()?
        };
        let maybe_cargo_toml_crate_repository_location = if direct_repo.is_some() {
            direct_repo
        } else {
            None
        };

        Ok(Self {
            crate_handle: crate_handle_obj,
            crate_name,
            version,
            consolidated_crate_interface,
            maybe_cargo_toml_package_authors,
            maybe_cargo_toml_rust_edition,
            maybe_cargo_toml_license,
            maybe_cargo_toml_crate_repository_location,
        })
    }
}

