/// Specifies how we want to bump a version:
///
/// - **Major** => X+1.0.0  
/// - **Minor** => X.Y+1.0  
/// - **Patch** => X.Y.Z+1  
/// - **Alpha(Option<u64>)** => X.Y.Z-alphaN  
/// # Behavior
/// 1. **Major**: Increment `ver.major`, reset minor/patch to 0, **clear** pre-release.  
///    Build metadata is retained (unchanged).
/// 2. **Minor**: Increment `ver.minor`, reset patch to 0, **clear** pre-release.  
///    Build metadata is retained.
/// 3. **Patch**: Increment `ver.patch`, **clear** pre-release.  
/// 4. **Alpha(n)**: Overwrite the existing pre-release with something like `"alpha{n}"`.
///    - If `n` is `None`, we default to `1` => `"alpha1"`.
///    - We do **not** remove or alter build metadata.
///    - If the alpha string fails to parse (very unlikely in practice),
///      we simply skip setting a new pre-release (so it remains `EMPTY`).
/// # Overflow
/// We do **not** guard against overflow if `ver.major` (or minor, patch) is near `u64::MAX`.
/// This is consistent with `semver` itself, which does not handle numeric overflow
/// in the major/minor/patch fields. In real usage, it's extremely rare to
/// approach `u64::MAX` for a version component.
/// # Example
/// ```
/// use workspacer_3p::semver::Version;
/// use workspacer_bump::ReleaseType;
/// let mut v = Version::parse("1.2.3").unwrap();
/// ReleaseType::Major.apply_to(&mut v);
/// assert_eq!(v.to_string(), "2.0.0");
#[derive(Debug, Clone)]
pub enum ReleaseType {
    Major,
    Minor,
    Patch,
    Alpha(Option<u64>),
}

/// A trait describing how to bump versions in a workspace.
#[async_trait]
pub trait BumpAll {
    type Error;
    async fn bump_all(&mut self, release: ReleaseType) -> Result<(), Self::Error>;
}


#[async_trait]
pub trait BumpCrateAndDownstreams {
    type Error;
    async fn bump_crate_and_downstreams(&mut self, crate_name: &mut CrateHandle, release: ReleaseType) -> Result<(), Self::Error>;
}


/// This will be implemented by CrateHandle
#[async_trait]
pub trait Bump {
    type Error;
    async fn bump(&mut self, release: ReleaseType) -> Result<(), Self::Error>;
}


#[async_trait]
pub trait WorkspaceDownstreamExt {
    async fn update_downstreams_recursively(&mut self, dep_name: &str, new_version: &semver::Version, visited: &mut HashSet<String>) -> Result<(), WorkspaceError>;
}

/// Macro that generates an `impl BumpAll for SomeWorkspace<P,T>` block.
/// Use it once for your real `Workspace<P,T>` and once for your `MockWorkspace<P,T>`.
#[macro_export]
macro_rules! gen_bump_all_for_workspace { /* macro body here */ }

impl ReleaseType {
    /// Increments a `semver::Version` in-place based on self, with the
    /// rules described above.
    pub fn apply_to(&self, ver: &mut Version) {
        match self {
            ReleaseType::Major => {
                // e.g. 1.2.3 -> 2.0.0
                ver.major = ver.major.wrapping_add(1);
                ver.minor = 0;
                ver.patch = 0;
                // Clear pre-release
                ver.pre = Prerelease::EMPTY;
            }
            ReleaseType::Minor => {
                // e.g. 1.2.3 -> 1.3.0
                ver.minor = ver.minor.wrapping_add(1);
                ver.patch = 0;
                // Clear pre-release
                ver.pre = Prerelease::EMPTY;
            }
            ReleaseType::Patch => {
                // e.g. 1.2.3 -> 1.2.4
                ver.patch = ver.patch.wrapping_add(1);
                // Clear pre-release
                ver.pre = Prerelease::EMPTY;
            }
            ReleaseType::Alpha(opt_n) => {
                // Overwrite pre-release with e.g. "alpha1" or "alphaN"
                ver.pre = Prerelease::EMPTY;
                let n = opt_n.unwrap_or(1); // default 1 if None
                let alpha_str = format!("alpha{}", n);
                match Prerelease::new(&alpha_str) {
                    Ok(pr) => ver.pre = pr,
                    Err(_) => {
                        // If we somehow parse a weird alpha string, skip setting it
                        // e.g. "alpha9999999999999999999999999" might fail if it’s too big
                        // But in practice it's still ASCII, so it'd likely parse fine.
                    }
                }
            }
        }
    }
}

impl<T> Bump for T where T: ValidateIntegrity<Error = CrateError> + HasCargoToml + HasCargoTomlPathBuf<Error = CrateError> + AsRef<Path> + Send + Sync {
    type Error = CrateError;
    async fn bump(&mut self, release: ReleaseType) -> Result<(), Self::Error> {
        trace!("Entered Bump::bump with release={:?}", release);

        // A) Lock briefly just to *read* the old version
        let old_version_str = {
            let cargo_toml_arc = self.cargo_toml();
            let guard = cargo_toml_arc.lock().await;

            // read old version as a string, BUT unify missing file => IoError
            let ver = match guard.version() {
                Err(CargoTomlError::FileNotFound { missing_file }) => {
                    error!("bump(): mapping 'FileNotFound' to CrateError::IoError");
                    return Err(CrateError::IoError {
                        io_error: Arc::new(std::io::Error::new(
                            std::io::ErrorKind::NotFound,
                            format!("Cargo.toml not found at {}", missing_file.display())
                        )),
                        context: format!("Cannot read Cargo.toml at {:?}", missing_file),
                    });
                }
                Err(e) => {
                    error!("bump(): got CargoTomlError => returning CrateError::CargoTomlError({:?})", e);
                    return Err(CrateError::CargoTomlError(e));
                }
                Ok(ver_ok) => ver_ok,
            };
            let ver_str = ver.to_string();
            debug!("Current version (before bump) is '{}', about to do integrity check", ver_str);
            ver_str
        };

        // B) Now do sabotage check and forced re-parse from disk
        trace!("Validating crate integrity before proceeding with bump");
        self.validate_integrity().await?;

        // C) Re-lock to do the actual bump patch
        let cargo_toml_path;
        let new_version_str;
        {
            let cargo_toml_arc = self.cargo_toml();
            let mut guard = cargo_toml_arc.lock().await;

            // parse the old version again (fresh)
            let mut old_ver = match guard.version() {
                Err(CargoTomlError::FileNotFound { missing_file }) => {
                    error!("bump(): second read => mapping 'FileNotFound' to IoError");
                    return Err(CrateError::IoError {
                        io_error: Arc::new(std::io::Error::new(
                            std::io::ErrorKind::NotFound,
                            format!("Cargo.toml not found at {}", missing_file.display())
                        )),
                        context: format!("Cannot re-read Cargo.toml at {:?}", missing_file),
                    });
                }
                Err(e) => {
                    error!("bump(): second read => CargoTomlError => returning CrateError::CargoTomlError({:?})", e);
                    return Err(CrateError::CargoTomlError(e));
                }
                Ok(ver_ok) => ver_ok,
            };
            let old_clone = old_ver.clone();

            // apply the release
            release.apply_to(&mut old_ver);

            // preserve the old build metadata
            old_ver.build = old_clone.build.clone();

            // Overwrite in-memory
            let bumped = old_ver.to_string();
            {
                let pkg = guard.get_package_section_mut()?;
                // same code as before for setting the version in the table
                if let Some(tbl) = pkg.as_table_mut() {
                    tbl.insert("version".to_owned(), toml::Value::String(bumped.clone()));
                    debug!("Set `package.version` to '{}'", bumped);
                } else {
                    error!("`package` section was not a TOML table; cannot set version!");
                    return Err(CrateError::CouldNotSetPackageVersionBecausePackageIsNotATable);
                }
            }

            cargo_toml_path = self.as_ref().join("Cargo.toml");
            new_version_str = bumped;
        } // drop lock

        // D) Finally save to disk outside the lock
        {
            let cargo_toml_arc = self.cargo_toml();
            let mut guard = cargo_toml_arc.lock().await;
            guard.save_to_disk().await?;
        }

        info!(
            "Successfully bumped crate at {:?} from {} to {}",
            cargo_toml_path, old_version_str, new_version_str
        );
        Ok(())
    }
}

impl<P, H> BumpCrateAndDownstreams for Workspace<P, H> where for<'async_trait> P: From<PathBuf> + AsRef<Path> + Send + Sync + 'async_trait, H: CrateHandleInterface<P> + Bump<Error = CrateError> + Send + Sync {
    type Error = WorkspaceError;
    async fn bump_crate_and_downstreams(&mut self, crate_handle: &mut CrateHandle, release: ReleaseType) -> Result<(), Self::Error> {
        trace!(
            "bump_crate_and_downstreams: bumping '{}' => release={:?}",
            crate_handle.name(),
            release
        );

        // 1) Attempt to bump
        if let Err(err) = crate_handle.bump(release.clone()).await {
            error!("Error bumping crate '{}': {:?}", crate_handle.name(), err);
            return Err(WorkspaceError::BumpError {
                crate_path: crate_handle.as_ref().join("Cargo.toml"),
                source: Box::new(err),
            });
        }

        let new_ver = crate_handle.version().map_err(|ver_err| {
            error!("Could not re-parse new version for '{}': {:?}", crate_handle.name(), ver_err);
            WorkspaceError::CrateError(ver_err)
        })?;

        info!(
            "bump_crate_and_downstreams: crate='{}' => new_ver={}",
            crate_handle.name(),
            new_ver
        );

        let crate_key = crate_handle.name().to_string();
        let mut visited = HashSet::new();
        visited.insert(crate_key.clone());

        self.update_downstreams_recursively(&crate_key, &new_ver, &mut visited).await
    }
}

impl<P, H> WorkspaceDownstreamExt for Workspace<P, H> where for<'async_trait> P: From<PathBuf> + AsRef<Path> + Send + Sync + 'async_trait, H: CrateHandleInterface<P> + Bump<Error = CrateError> + Send + Sync {
    async fn update_downstreams_recursively(&mut self, dep_name: &str, new_version: &semver::Version, visited: &mut HashSet<String>) -> Result<(), WorkspaceError> {

        // 1) local copy of crates
        let crate_list: Vec<_> = self.crates().iter().cloned().collect();

        for arc_crate in crate_list {
            let crate_name = {
                let h = arc_crate.lock().await;
                h.name().to_string()
            };
            if visited.contains(&crate_name) {
                continue;
            }

            // 2) lock for short, synchronous update
            let changed = {

                let mut h          = arc_crate.lock().await;
                let toml           = h.cargo_toml();
                let mut toml_guard = toml.lock().await;

                // do in-memory updates
                let changed = toml_guard.update_dependency_version(dep_name, &new_version.to_string())?;

                changed
                // guard dropped
            };

            if changed {
                // 3) do async save, once the guard is dropped
                {
                    let crate_guard = arc_crate.lock().await;

                    let toml = crate_guard.cargo_toml();

                    let mut toml_guard = toml.lock().await;

                    toml_guard.save_to_disk().await?;
                }

                visited.insert(crate_name.clone());
                self.update_downstreams_recursively(&crate_name, new_version, visited).await?;
            }
        }

        Ok(())
    }
}

