    leading_comments: Option<String>,
}


#[derive(Clone,Builder,Getters,Debug)]
#[builder(setter(into),build_fn(name = "private_build"))]
#[getset(get="pub")]
pub struct TopBlockMacro {
    stem: String,
    leading_comments: Option<String>,
}

/// Builds the final snippet for the "has_imports_line=false" scenario:
/// (a) snippet lines first,
/// (b) then old_top_macros,
/// (c) then new_top_macros.
pub fn build_top_block_for_no_imports_line(old_top_macros: &[TopBlockMacro], non_macro_lines: &[String], new_top_macros: &[TopBlockMacro]) -> String {
    trace!("Entering build_top_block_for_no_imports_line");
    let mut buffer = String::new();

    // 1) snippet lines
    for (i, line) in non_macro_lines.iter().enumerate() {
        maybe_push_newline(&mut buffer);
        buffer.push_str(line);
        if i < non_macro_lines.len() - 1 {
            buffer.push('\n');
        }
    }

    // 2) old macros
    for om in old_top_macros {
        maybe_push_newline(&mut buffer);
        push_macro_with_comments(&mut buffer, om);
    }

    // 3) new macros
    for nm in new_top_macros {
        maybe_push_newline(&mut buffer);
        push_macro_with_comments(&mut buffer, nm);
    }

    debug!("build_top_block_for_no_imports_line => length={}", buffer.len());
    trace!("Exiting build_top_block_for_no_imports_line");
    buffer
}


/// Builds a string with one line per TopBlockMacro, preserving each macro’s leading comments
/// and ensuring each macro ends up on its own line (with no trailing newline).
pub fn create_top_block_text(tops: &[TopBlockMacro]) -> String {
    trace!("Entering create_top_block_text");
    debug!("tops.len()={}", tops.len());

    let mut buffer = String::new();

    for top in tops {
        // (1) Insert the macro’s leading comments, but only insert a
        //     separating newline if the buffer is *non-empty*.
        if let Some(comments) = top.leading_comments() {
            if !buffer.is_empty() && !buffer.ends_with('\n') {
                buffer.push('\n');
            }
            buffer.push_str(comments);
            // Ensure there's exactly one newline after the comment block
            if !buffer.ends_with('\n') {
                buffer.push('\n');
            }
        }

        // (2) Then add the macro line, e.g. `x!{stem}`
        //     always add a trailing newline, which we’ll trim at the end.
        buffer.push_str(&format!("x!{{{}}}\n", top.stem()));
    }

    // (3) Trim trailing newlines
    while buffer.ends_with('\n') {
        buffer.pop();
    }

    debug!("Exiting create_top_block_text =>\n{}", buffer);
    buffer
}


/// Removes from `new_macros` any macro whose stem is already in `old_macros`.
pub fn filter_new_macros_for_duplicates(old_macros: &[TopBlockMacro], new_macros: &[TopBlockMacro]) -> Vec<TopBlockMacro> {
    // gather old stems into a Set
    let old_stems: std::collections::HashSet<_> =
        old_macros.iter().map(|om| om.stem().to_owned()).collect();

    // keep only new macros whose stem is not in old_macros
    new_macros
        .iter()
        .filter(|nm| !old_stems.contains(nm.stem()))
        .cloned()
        .collect()
}


pub fn is_x_macro(item: &ast::Item) -> Option<String> {
    trace!("Entering is_x_macro");

    let mac_call = ast::MacroCall::cast(item.syntax().clone())?;
    let path = mac_call.path()?;
    let path_str = path.syntax().text().to_string();
    trace!("Parsed macro path='{}'", path_str);

    // Trim and ensure the path is exactly "x" without internal spaces.
    let path_str = path_str.trim();
    if path_str != "x" || path_str.contains(' ') {
        trace!("Not an x! macro => returning None");
        return None;
    }

    let full_text = item.syntax().text().to_string();

    // Ensure the macro has braces; otherwise, it's invalid
    if !full_text.contains('{') || !full_text.contains('}') {
        trace!("Missing braces in macro, not recognized as x! macro");
        return None;
    }

    // Enforce that the source text actually contains "x!"
    // (no whitespace is allowed between `x` and `!`)
    if !full_text.contains("x!") {
        trace!("No direct 'x!' substring found => spacing or mismatch => returning None");
        return None;
    }

    // Ensure there are no spaces around the entire macro (leading/trailing)
    if full_text != full_text.trim() {
        trace!("Invalid spacing around the macro, rejected");
        return None;
    }

    debug!("Recognized x! macro => returning full_text='{}'", full_text);
    Some(full_text)
}


/// Rebuilds the final text by copying `old_text` except for old macros,
/// and inserting the `final_top_block` at `insertion_offset`.
/// This version ensures:
///    1) We don’t produce double newlines if final_top_block or old_text already ends with a newline.
///    2) If insertion_offset points exactly to a newline and we just forced a newline
///       for final_top_block, we skip copying old_text’s newline again.
pub fn splice_top_block_into_source(old_text: &str, old_macros: &[ExistingXMacro], insertion_offset: usize, final_top_block: &str) -> String {
    trace!("Entering splice_top_block_into_source (insertion_offset={}, block_len={})",
           insertion_offset, final_top_block.len());

    let mut out = String::new();
    let mut pos = 0;
    let mut inserted_block = false;
    let mut macros_iter = old_macros.iter().peekable();

    while pos < old_text.len() {
        // Check if we should insert final_top_block here
        if !inserted_block && insertion_offset >= pos {
            let next_macro_start = macros_iter
                .peek()
                .map(|em| em.range().start().into())
                .unwrap_or(old_text.len());
            trace!("next_macro_start={}, insertion_offset={}", next_macro_start, insertion_offset);

            if insertion_offset <= next_macro_start {
                debug!("Inserting final_top_block at offset={}", insertion_offset);
                // Copy up to insertion_offset
                if insertion_offset > pos {
                    out.push_str(&old_text[pos..insertion_offset]);
                    pos = insertion_offset;
                }

                // Insert final_top_block
                if !final_top_block.is_empty() {
                    // If out doesn't end with a newline, add one
                    if !out.ends_with('\n') {
                        out.push('\n');
                    }
                    // Push the block text
                    out.push_str(final_top_block);

                    // Ensure exactly one trailing newline after the block
                    if !out.ends_with('\n') {
                        out.push('\n');
                    }

                    //
                    // [FIX] If old_text has a newline at insertion_offset,
                    // and we've already added a newline for final_top_block,
                    // skip that upcoming newline to avoid duplicates.
                    //
                    // i.e. if "abcde\n" has insertion_offset=5 => we wrote "\nBLOCK\n" 
                    // so final => "abcde\nBLOCK\n". If old_text[5] == '\n', 
                    // we skip that newline from old_text.
                    //
                    if pos < old_text.len() && old_text.as_bytes()[pos] == b'\n' {
                        debug!("Skipping original newline at old_text[{}], to avoid double-newline", pos);
                        pos += 1;
                    }
                }
                inserted_block = true;
            }
        }

        // Skip or copy around macros
        if let Some(m) = macros_iter.peek() {
            let m_start: usize = m.range().start().into();
            let m_end:   usize = m.range().end().into();
            trace!("macro range=({}..{})", m_start, m_end);

            if pos < m_start {
                let slice_end = m_start.min(old_text.len());
                debug!("Copying old_text[{}..{}]", pos, slice_end);
                out.push_str(&old_text[pos..slice_end]);
                pos = slice_end;
            } else if pos < m_end {
                debug!("Skipping macro region [{}..{}]", m_start, m_end);
                pos = m_end;
                macros_iter.next();
            } else {
                macros_iter.next();
            }
        } else {
            debug!("No more macros => copying remainder old_text[{}..]", pos);
            out.push_str(&old_text[pos..]);
            pos = old_text.len();
        }
    }

    // If block wasn't inserted yet, append at the end
    if !inserted_block && !final_top_block.is_empty() {
        debug!("Never inserted block => appending at end");
        if !out.ends_with('\n') {
            out.push('\n');
        }
        out.push_str(final_top_block);
        if !out.ends_with('\n') {
            out.push('\n');
        }
    }

    debug!("splice_top_block_into_source done, final length={}", out.len());
    trace!("Exiting splice_top_block_into_source");
    out
}


pub fn collect_existing_x_macros(parsed_file: &SourceFile) -> Vec<ExistingXMacro> {
    trace!("Entering collect_existing_x_macros");
    let mut result = Vec::new();

    for item in parsed_file.items() {
        // 1) Check if this item is recognized by is_x_macro => returns full_text
        if let Some(macro_text) = is_x_macro(&item) {
            let rng = item.syntax().text_range();
            debug!("Found x! macro at range={:?}, text='{}'", rng, macro_text);

            // 2) Gather preceding line comments so we can reattach them
            let mut leading_comments = gather_leading_comments(&item);

            // 3) If leading_comments is empty, but the macro_text itself starts with "//"
            //    then RA likely merged the comment lines into the same node, e.g. 
            //    `"// Hello alpha\nx!{alpha}"`. We'll parse them out:
            if leading_comments.is_empty() && macro_text.trim_start().starts_with("//") {
                // We'll do a naive approach: take the lines from `macro_text` until the line with `x!{`,
                // if they look like `// ...`.
                let mut lines = macro_text.lines().collect::<Vec<_>>();
                if let Some(idx_x) = lines.iter().position(|ln| ln.contains("x!{")) {
                    let comment_part = &lines[0..idx_x];
                    // Filter to keep only lines that truly look like `// ...`.
                    let comment_lines: Vec<&str> = comment_part
                        .iter()
                        .filter(|ln| ln.trim_start().starts_with("//"))
                        .copied()
                        .collect();

                    if !comment_lines.is_empty() {
                        let joined = comment_lines.join("\n");
                        // Ensure exactly one trailing newline
                        let final_comment = if joined.ends_with('\n') {
                            joined
                        } else {
                            format!("{joined}\n")
                        };
                        leading_comments = final_comment;
                    }
                }
            }

            // 4) Build the ExistingXMacro
            let existing_x_macro = ExistingXMacroBuilder::default()
                .text(macro_text)
                .range(rng)
                .leading_comments(leading_comments)
                .build()
                .unwrap();
            result.push(existing_x_macro);
        }
    }

    // Sort by ascending start offset
    result.sort_by_key(|em| em.range().start());
    trace!("Exiting collect_existing_x_macros with {} macros", result.len());
    result
}


pub fn gather_deduplicated_macro_stems(old_macros: &[ExistingXMacro], new_top_block: &str) -> Vec<String> {
    trace!("Entering gather_deduplicated_macro_stems");

    fn extract_stem(x_macro_text: &str) -> Option<String> {
        let start = x_macro_text.find('{')?;
        let end   = x_macro_text.rfind('}')?;
        if start + 1 <= end {
            Some(x_macro_text[start+1..end].trim().to_string())
        } else {
            None
        }
    }

    // old stems
    let mut stems: Vec<String> = old_macros
        .iter()
        .filter_map(|em| {
            let s = extract_stem(em.text());
            trace!("From old macro text='{}' => stem={:?}", em.text(), s);
            s
        })
        .collect();

    // parse macros out of new_top_block
    let parsed_newblock = SourceFile::parse(new_top_block, Edition::Edition2021).tree();
    for item in parsed_newblock.items() {
        if let Some(txt) = is_x_macro(&item) {
            if let Some(stm) = extract_stem(&txt) {
                debug!("Found new top_block macro with stem='{}'", stm);
                stems.push(stm);
            } else {
                trace!("Unable to parse stem from macro text='{}'", txt);
            }
        }
    }

    stems.sort();
    stems.dedup();
    debug!("Final deduplicated stems: {:?}", stems);

    trace!("Exiting gather_deduplicated_macro_stems");
    stems
}


/// A helper that walks backward from `item.syntax()` to pick up line-comments,
/// similarly to what we do for old macros. If no separate tokens are found,
/// but the item’s own text starts with `//`, we parse those lines directly from 
/// `full_text` as a fallback.
pub fn gather_leading_comments(item: &ast::Item) -> String {
    let mut lines = Vec::new();
    let mut cur = item.syntax().prev_sibling_or_token();
    let mut encountered_blank = false;

    // 1) Normal RA-based walk upward, collecting comments from preceding tokens
    while let Some(n_or_t) = cur {
        match n_or_t {
            NodeOrToken::Token(tok) => {
                let kind = tok.kind();
                let txt  = tok.text().to_string();

                match kind {
                    SyntaxKind::COMMENT => {
                        if encountered_blank {
                            break;
                        }
                        // Prepend
                        lines.push(txt);
                    }
                    SyntaxKind::WHITESPACE => {
                        // If there's a blank line => stop
                        if txt.matches('\n').count() >= 2 {
                            encountered_blank = true;
                            break;
                        }
                    }
                    _ => {
                        // Some non-comment => stop
                        break;
                    }
                }
                // Move upward
                cur = tok.prev_sibling_or_token();
            }
            NodeOrToken::Node(_) => {
                // Another node => stop
                break;
            }
        }
    }

    lines.reverse();
    let mut joined = if !lines.is_empty() {
        // We found at least one preceding comment token => join them
        let tmp = lines.join("\n");
        // Ensure exactly one trailing newline
        if tmp.ends_with('\n') { tmp } else { format!("{tmp}\n") }
    } else {
        String::new()
    };

    // 2) Fallback: If joined is empty but the item text itself starts with `//`, 
    // RA likely merged top-of-file comment lines into the same syntax node. 
    // We'll parse them out from the front of the item’s full text, stopping 
    // at the first blank line or any line that doesn't start with `//`.
    if joined.is_empty() {
        let full_text = item.syntax().text().to_string();
        let trimmed = full_text.trim_start();
        if trimmed.starts_with("//") {
            // We'll gather consecutive lines of the form `// ...`, 
            // stopping at the first blank line or a line that doesn't start with `//`.
            let mut out = Vec::new();
            for line in full_text.lines() {
                let tline = line.trim_start();
                if tline.starts_with("//") {
                    out.push(line);
                } else if tline.is_empty() {
                    // a blank line => stop
                    break;
                } else {
                    // a non-comment line => stop
                    break;
                }
            }
            if !out.is_empty() {
                let tmp = out.join("\n");
                // ensure exactly one trailing newline
                joined = if tmp.ends_with('\n') {
                    tmp
                } else {
                    format!("{tmp}\n")
                };
            }
        }
    }

    joined
}


pub fn find_top_block_insertion_offset(parsed_file: &SourceFile, edited_text: &str) -> Result<usize, SourceFileRegistrationError> {
    trace!("Entering find_top_block_insertion_offset");
    let mut earliest_offset: Option<usize> = None;

    for item in parsed_file.items() {
        let start = item.syntax().text_range().start();
        let start_usize = usize::from(start);
        trace!("Examining item with start={}", start_usize);

        if earliest_offset.map_or(true, |prev| start_usize < prev) {
            debug!("Updating earliest_offset from {:?} to {}", earliest_offset, start_usize);
            earliest_offset = Some(start_usize);
        }
    }

    let final_offset = earliest_offset.unwrap_or_else(|| {
        debug!("No items => default offset is end of edited_text={}", edited_text.len());
        edited_text.len()
    });

    debug!("Final insertion offset is {}", final_offset);
    trace!("Exiting find_top_block_insertion_offset");
    Ok(final_offset)
}


pub fn existing_macros_to_top_block_macros(old_macros: &[ExistingXMacro]) -> Vec<TopBlockMacro> {
    let mut out = vec![];
    for em in old_macros {
        if let Some(stem) = extract_stem(em.text()) {
            // Transform empty/whitespace-only comments into None
            let leading = match em.leading_comments() {
                Some(s) => {
                    let trimmed = s.trim();
                    if trimmed.is_empty() {
                        None
                    } else {
                        Some(s.clone())
                    }
                }
                None => None,
            };

            let macr = TopBlockMacroBuilder::default()
                .stem(stem)
                .leading_comments(leading)
                .build()
                .unwrap();

            out.push(macr);
        }
    }
    out
}


/// Builds the final top-block snippet by combining:
///   - old_top_macros (possibly with leading comments),
///   - user-provided non-macro lines (like snippet lines),
///   - new_top_macros (possibly with leading comments),
/// in either "imports line" order or "no imports" order.
/// 
/// This is a pure function: it does *not* parse or modify old_text, 
/// it simply assembles the final snippet into a `String`.
pub fn assemble_final_top_block_snippet(has_imports_line: bool, old_top_macros: &[TopBlockMacro], new_top_macros: &[TopBlockMacro], non_macro_lines: &[String]) -> String {
    trace!("Entering assemble_final_top_block_snippet");
    debug!("has_imports_line={}", has_imports_line);
    debug!(
        "old_top_macros.len()={}, new_top_macros.len()={}, non_macro_lines.len()={}",
        old_top_macros.len(),
        new_top_macros.len(),
        non_macro_lines.len()
    );

    // We'll produce the snippet in a buffer; then remove trailing newlines.
    let mut buffer = if has_imports_line {
        trace!("has_imports_line=true => old macros first, snippet lines, then new macros");
        build_top_block_for_imports_line(old_top_macros, non_macro_lines, new_top_macros)
    } else {
        trace!("has_imports_line=false => snippet lines first, old macros, then new macros");
        build_top_block_for_no_imports_line(old_top_macros, non_macro_lines, new_top_macros)
    };

    remove_trailing_newlines(&mut buffer);

    debug!(
        "assemble_final_top_block_snippet => final snippet length={}",
        buffer.len()
    );
    trace!("Exiting assemble_final_top_block_snippet");
    buffer
}


pub fn extract_non_macro_lines(new_top_block: &str) -> Vec<String> {
    trace!("Entering extract_non_macro_lines");
    debug!("new_top_block length={}", new_top_block.len());

    let mut lines = Vec::new();
    for line in new_top_block.split('\n') {
        if line.contains("x!{") {
            trace!("Skipping line containing x!{{...}}: '{}'", line);
        } else {
            trace!("Keeping line: '{}'", line);
            lines.push(line.to_string());
        }
    }

    debug!("Resulting lines: {:?}", lines);
    trace!("Exiting extract_non_macro_lines");
    lines
}


pub fn rebuild_librs_with_new_top_block(parsed_file: &SourceFile, old_text: &str, new_top_block: &str) -> Result<String, SourceFileRegistrationError> {
    trace!("Entering rebuild_librs_with_new_top_block");
    debug!("old_text length={}, new_top_block length={}", old_text.len(), new_top_block.len());

    // (1) Gather old macros
    let old_macros = collect_existing_x_macros(parsed_file);
    debug!("Found {} old macros in the file", old_macros.len());

    let old_top_macros = existing_macros_to_top_block_macros(&old_macros);
    debug!("Converted old macros => {} TopBlockMacro entries", old_top_macros.len());

    // (2) Parse new_top_block => new_macros + non-macro lines
    let new_macros = parse_new_macros_with_comments(new_top_block);
    let non_macro_lines = extract_non_macro_lines(new_top_block);
    debug!(
        "Found {} new macros + {} non-macro lines",
        new_macros.len(),
        non_macro_lines.len()
    );

    // (3) Check for imports => decide snippet order
    let has_imports_line = parsed_file.items().any(|it| is_imports_line(&it));
    debug!("has_imports_line={}", has_imports_line);

    // (3a) **Remove duplicates** so if the old file has x!{stuff_a}, we don’t add it again.
    let new_macros_filtered = filter_new_macros_for_duplicates(&old_top_macros, &new_macros);

    // (4) Build final snippet
    let final_top_block = assemble_final_top_block_snippet(
        has_imports_line,
        &old_top_macros,
        &new_macros_filtered,
        &non_macro_lines,
    );
    debug!(
        "Constructed final top block =>\n---\n{}\n--- (length={})",
        final_top_block,
        final_top_block.len()
    );

    // (5) Find insertion offset
    let earliest_offset = find_earliest_non_macro_item_offset(parsed_file, old_text);
    let maybe_import_end = find_last_import_end_before_offset(parsed_file, earliest_offset);
    let initial_offset   = maybe_import_end.unwrap_or(earliest_offset);
    let insertion_offset = snap_offset_to_newline(initial_offset, earliest_offset, old_text);
    debug!("insertion_offset={}", insertion_offset);

    // (6) Splice out old macros (already found) + put final_top_block in
    let final_text = splice_top_block_into_source(
        old_text,
        &old_macros,
        insertion_offset,
        &final_top_block,
    );
    debug!("Final text length = {}", final_text.len());
    trace!("Exiting rebuild_librs_with_new_top_block");
    Ok(final_text)
}


/// A small helper that ensures if the `buffer` is non-empty and doesn’t
/// end with `\n`, we push exactly one newline.  
pub fn maybe_push_newline(buffer: &mut String) {
    if !buffer.is_empty() && !buffer.ends_with('\n') {
        buffer.push('\n');
    }
}


pub fn find_earliest_non_macro_item_offset(parsed_file: &SourceFile, old_text: &str) -> usize {

    trace!("Entering find_earliest_non_macro_item_offset");

    let mut earliest = old_text.len();
    debug!("Initial earliest offset = old_text.len()={}", earliest);

    for item in parsed_file.items() {
        // Skip if this is an x! macro:
        if let Some(full_text) = is_x_macro(&item) {
            trace!("Skipping x! macro => full_text='{}'", full_text);
            continue;
        }

        // RA occasionally parses stray tokens like `;random tokens`
        // as a MacroCall but with no bang token. We only want to
        // treat actual macros (with a '!' present) or real items
        // as "non-macro items":
        if let Some(mc) = ast::MacroCall::cast(item.syntax().clone()) {
            if mc.excl_token().is_none() {
                trace!("Skipping partial macro call => no bang token");
                continue;
            }
        }

        let start: usize = item.syntax().text_range().start().into();
        trace!("Found a non-macro item at offset={}", start);
        if start < earliest {
            debug!("Updating earliest offset from {} to {}", earliest, start);
            earliest = start;
        }
    }

    debug!("Final earliest offset is {}", earliest);
    trace!("Exiting find_earliest_non_macro_item_offset");
    earliest
}


pub fn is_imports_line(item: &ast::Item) -> bool {
    trace!("Entering is_imports_line");

    if let Some(module_item) = ast::Module::cast(item.syntax().clone()) {
        if let Some(name_ident) = module_item.name() {
            let name_txt = name_ident.text();
            debug!("Module name='{}'", name_txt);
            let is_imports = name_txt == "imports";
            trace!("Returning {}", is_imports);
            return is_imports;
        }
    } else if let Some(use_item) = ast::Use::cast(item.syntax().clone()) {
        let text = use_item.syntax().text().to_string();
        trace!("Found a use item => text='{}'", text);
        if text.contains("imports::*") {
            debug!("This use line references imports::* => returning true");
            return true;
        }
    }

    trace!("Not recognized as an imports line => returning false");
    false
}


/// Removes trailing newlines from the provided buffer string (in-place).
pub fn remove_trailing_newlines(buffer: &mut String) {
    trace!("Entering remove_trailing_newlines");
    while buffer.ends_with('\n') {
        buffer.pop();
    }
    debug!("remove_trailing_newlines => final length={}", buffer.len());
    trace!("Exiting remove_trailing_newlines");
}


/// Builds the final snippet for the "has_imports_line=true" scenario:
/// (a) old_top_macros first (with their leading comments),
/// (b) then non-macro lines,
/// (c) then new_top_macros.
pub fn build_top_block_for_imports_line(old_top_macros: &[TopBlockMacro], non_macro_lines: &[String], new_top_macros: &[TopBlockMacro]) -> String {
    trace!("Entering build_top_block_for_imports_line");
    let mut buffer = String::new();

    // 1) old macros
    for om in old_top_macros {
        maybe_push_newline(&mut buffer);
        push_macro_with_comments(&mut buffer, om);
    }

    // 2) snippet lines
    for (i, line) in non_macro_lines.iter().enumerate() {
        maybe_push_newline(&mut buffer);
        buffer.push_str(line);
        // if not last line => push another newline
        if i < non_macro_lines.len() - 1 {
            buffer.push('\n');
        }
    }

    // 3) new macros
    for nm in new_top_macros {
        maybe_push_newline(&mut buffer);
        push_macro_with_comments(&mut buffer, nm);
    }

    debug!("build_top_block_for_imports_line => length={}", buffer.len());
    trace!("Exiting build_top_block_for_imports_line");
    buffer
}


pub fn collect_existing_mod_macro_stems(parsed_file: &SourceFile) -> Result<Vec<String>, SourceFileRegistrationError> {
    trace!("Entering collect_existing_mod_macro_stems");
    let mut stems = vec![];

    // Iterate top-level items: these are `ast::Item` in ra_ap_syntax.
    for item in parsed_file.items() {
        trace!("Examining a top-level item: {:?}", item.syntax().text());

        if let Some(mac_item) = ast::MacroCall::cast(item.syntax().clone()) {
            // Check for any outer attributes
            let attr_count = mac_item.attrs().count();
            trace!("Found a MacroCall with {} attributes", attr_count);

            if attr_count > 0 {
                error!("Found an unhandled top-level macro with attributes => bail");
                return Err(SourceFileRegistrationError::FoundAnUnhandlableTopLevelMacroCallWithAttributes);
            }

            // Make sure it's `x!{ ... }`
            if let Some(path) = mac_item.path() {
                let path_text = path.syntax().text().to_string();
                trace!("Macro path text: '{}'", path_text);

                if path_text.trim() == "x" {
                    // Extract what's inside the macro
                    if let Some(tt) = mac_item.token_tree() {
                        let macro_inner = tt.syntax().text().to_string();
                        debug!("macro_inner = '{}'", macro_inner);

                        let chunk = macro_inner.trim_matches([' ', '{', '}', ',']).to_string();
                        if chunk.contains(',') {
                            error!("Detected multiple items in x! macro => bail. chunk='{}'", chunk);
                            return Err(SourceFileRegistrationError::MultipleItemsInXMacroUnsupported { chunk });
                        }
                        trace!("Pushing stem '{}'", chunk);
                        stems.push(chunk);
                    }
                }
            }
        } else if let Some(mod_item) = ast::Module::cast(item.syntax().clone()) {
            // If user wrote `pub mod foo;` we bail, since that might conflict with x! usage
            if let Some(name_ident) = mod_item.name() {
                let mod_name = name_ident.text().to_string();
                if !mod_name.is_empty() && mod_name != "imports" {
                    warn!("Found a raw mod '{}', which we don't handle => error out", mod_name);
                    return Err(SourceFileRegistrationError::FoundARawModNameWhichWeDontHandlePleaseRemoveOrUnifyWithXMacros {
                        mod_name
                    });
                }
            }
        } else {
            trace!("Not a MacroCall nor a recognizable mod => ignoring");
        }
    }

    debug!("Final stems collected: {:?}", stems);
    trace!("Exiting collect_existing_mod_macro_stems");
    Ok(stems)
}


