pub fn parse_new_macros_with_comments(new_top_block: &str) -> Vec<TopBlockMacro> {
    use ra_ap_syntax::{Edition, SourceFile};

    let parse = SourceFile::parse(new_top_block, Edition::Edition2021);
    let file = parse.tree();
    let mut results = vec![];

    for item in file.items() {
        if let Some(full_text) = is_x_macro(&item) {
            // Extract macro’s stem
            if let Some(stem) = extract_stem(&full_text) {
                // Normal gather of doc lines:
                let leading = gather_leading_comments(&item);
                let mac = TopBlockMacroBuilder::default()
                    .stem(stem)
                    .leading_comments(leading)
                    .build()
                    .unwrap();
                results.push(mac);
            }
        }
    }
    results
}


/// A small helper for pushing a `TopBlockMacro` (leading comments + `x!{stem}`),
/// ensuring each part ends in exactly one `\n` if needed. 
/// 
/// **Key points**:
///  - If `buffer` is non-empty and doesn't end with `\n`, push one before anything else.
///  - Then write the macro's leading comments (if any).
///  - If those comments do **not** end in `\n`, push one.
///  - Finally, append `x!{stem}`.
pub fn push_macro_with_comments(buffer: &mut String, mac: &TopBlockMacro) {
    // 1) Ensure buffer is separated from new content by one newline.
    maybe_ensure_newline(buffer);

    // 2) If there are leading comments, push them, ensuring they end with newline.
    if let Some(comments) = mac.leading_comments() {
        buffer.push_str(comments);
        if !buffer.ends_with('\n') {
            buffer.push('\n');
        }
    }

    // 3) Write the macro call.
    buffer.push_str(&format!("x!{{{}}}", mac.stem()));
}


pub fn extract_stem(full_text: &str) -> Option<String> {
    let start = full_text.find('{')?;
    let end   = full_text.rfind('}')?;
    Some(full_text[start+1 .. end].trim().to_string())
}


pub fn find_last_import_end_before_offset(parsed_file: &SourceFile, earliest_offset: usize) -> Option<usize> {
    trace!(
        "Entering find_last_import_end_before_offset with earliest_offset={}",
        earliest_offset
    );

    let file_text = parsed_file.syntax().text().to_string();
    let file_len = file_text.len();
    let mut answer = None;

    for item in parsed_file.items() {
        if is_imports_line(&item) {
            let rng = item.syntax().text_range();
            let start: usize = rng.start().into();
            let end:   usize = rng.end().into();
            trace!("Found an imports line from {}..{}", start, end);

            // We'll find the end of the *entire* physical line from `start`.
            let line_end = find_line_end(&file_text, start);
            debug!(
                "Computed line_end={}, earliest_offset={}, start={}",
                line_end, earliest_offset, start
            );

            // If the line is entirely before earliest_offset, or it starts
            // at earliest_offset (partial overlap), we treat it as needing
            // to shift our insertion point to after line_end.
            let final_end = if line_end <= earliest_offset {
                trace!("Line ends on/before earliest_offset => final_end=line_end={}", line_end);
                line_end
            } else if start <= earliest_offset {
                trace!(
                    "Line starts before or exactly at earliest_offset => partial overlap => final_end=line_end={}",
                    line_end
                );
                line_end
            } else {
                trace!(
                    "Line starts after earliest_offset => ignoring (start={})",
                    start
                );
                continue;
            };

            if answer.map_or(true, |prev| final_end > prev) {
                debug!("Updating answer from {:?} to {}", answer, final_end);
                answer = Some(final_end);
            }
        } else {
            trace!("Not an imports line => skipping");
        }
    }

    debug!("Result = {:?}", answer);
    trace!("Exiting find_last_import_end_before_offset");
    answer
}


/// Rounds an offset up to the next newline if it's in the middle of a line,
/// without exceeding `earliest_offset`.
pub fn snap_offset_to_newline(initial_offset: usize, earliest_offset: usize, old_text: &str) -> usize {
    trace!("Entering snap_offset_to_newline with initial_offset={}, earliest_offset={}", 
           initial_offset, earliest_offset);

    if initial_offset >= old_text.len() {
        debug!("initial_offset >= old_text.len(), returning it as-is");
        return initial_offset;
    }
    if old_text.chars().nth(initial_offset) == Some('\n') {
        debug!("Already at a newline => returning initial_offset unchanged");
        return initial_offset;
    }

    trace!("Searching for next newline from offset={}", initial_offset);
    if let Some(rel_nl_pos) = old_text[initial_offset..].find('\n') {
        let abs_nl = initial_offset + rel_nl_pos + 1;
        let snapped = abs_nl.min(earliest_offset);
        debug!("Found newline at abs_nl={}, clamped to {} => returning {}", abs_nl, earliest_offset, snapped);
        snapped
    } else {
        debug!("No newline found => returning old_text.len()");
        old_text.len()
    }
}

impl<P,H> EnsureAllSourceFilesAreRegistered for Workspace<P,H> where for<'async_trait> P: From<PathBuf> + AsRef<Path> + Clone + Send + Sync + 'async_trait, H: CrateHandleInterface<P> + EnsureAllSourceFilesAreRegistered<Error=SourceFileRegistrationError> + Send + Sync {
