            ($vec:expr, $f:expr) => {
                for (i, item) in $vec.iter().enumerate() {
                    writeln!($f, "{}", item)?;
                    if i + 1 < $vec.len() {
                        writeln!($f)?;
                    }
                }
            };
        }

