        print_items!(self.traits, f);
        print_items!(self.type_aliases, f);
        print_items!(self.macros, f);
        print_items!(self.structs, f);
        print_items!(self.fns, f);
        print_items!(self.impls, f);
        print_items!(self.modules, f);

