/// Extract doc lines from `///` or `/** ... */`. We do NOT gather `#[doc="..."]` attributes here.
/// Those can be handled separately if you want to unify them.
pub fn extract_docs(node: &SyntaxNode) -> Option<String> {
    let mut doc_lines = Vec::new();

    for child in node.children_with_tokens() {
        if let Some(token) = child.into_token() {
            if token.kind() == SyntaxKind::COMMENT {
                let text = token.text();
                // We only consider `///` and `/**...*/` doc comments
                if text.starts_with("///") || text.starts_with("/**") {
                    debug!(?text, "Found doc-comment token");
                    // Keep lines as-is, so block docs remain `/** ... */`
                    for line in text.lines() {
                        // Trim leading indentation if you like:
                        doc_lines.push(line.trim_start().to_string());
                    }
                }
            }
        }
    }

    if doc_lines.is_empty() {
        None
    } else {
        Some(doc_lines.join("\n"))
    }
}


/// Minimal post-processing to ensure correct spacing around arrows, where clauses, etc.
pub fn post_process_spacing(signature: &str) -> String {
    signature
        .replace(")->", ") ->")
        .replace(">where", "> where")
}


/// Check if a node is “public,” e.g. `pub fn`, `pub struct`, or `#[macro_export]`.
pub fn is_node_public(node: &SyntaxNode) -> bool {
    let has_visibility = || {
        node.children()
            .find_map(ast::Visibility::cast)
            .map_or(false, |vis| {
                let text = vis.syntax().text().to_string();
                text.starts_with("pub")
            })
    };

    let kind = node.kind();
    let is_public = match kind {
        SyntaxKind::FN
        | SyntaxKind::STRUCT
        | SyntaxKind::ENUM
        | SyntaxKind::TRAIT
        | SyntaxKind::TYPE_ALIAS => has_visibility(),

        SyntaxKind::MACRO_RULES => {
            // special check if there's an attribute like #[macro_export]
            if let Some(macro_node) = ast::MacroRules::cast(node.clone()) {
                for attr in macro_node.attrs() {
                    if let Some(meta) = attr.meta() {
                        if let Some(path_node) = meta.path() {
                            if path_node.syntax().text().to_string() == "macro_export" {
                                return true;
                            }
                        }
                    }
                }
            }
            false
        }

        _ => false,
    };

    debug!("Node kind: {:?}, is_public: {}", kind, is_public);
    is_public
}

impl GenerateSignature for ast::Enum {
    fn generate_signature_with_opts(&self, opts: &SignatureOptions) -> String {
        trace!("Generating signature for ast::Enum with opts: {:?}", opts);

        let doc_text = if *opts.include_docs() {
            extract_docs(&self.syntax())
                .map(|d| format!("{}\n", d))
                .unwrap_or_default()
        } else {
            "".to_string()
        };

        let vis_str = self
            .visibility()
            .map(|v| format!("{} ", v.syntax().text()))
            .unwrap_or_default();

        let name = self
            .name()
            .map(|n| n.text().to_string())
            .unwrap_or_else(|| "<unknown_enum>".to_string());

        let generic_params_raw = self
            .generic_param_list()
            .map(|g| g.syntax().text().to_string())
            .unwrap_or_default();

        let where_clause_raw = self
            .where_clause()
            .map(|wc| wc.syntax().text().to_string())
            .unwrap_or_default();
        let where_clause = if where_clause_raw.is_empty() {
            "".to_string()
        } else {
            format!(" {}", where_clause_raw)
        };

        // If fully_expand, we gather actual variants:
        let variants_text = if *opts.fully_expand() {
            if let Some(variant_list) = self.variant_list() {
                let items: Vec<String> = variant_list
                    .variants()
                    .map(|v| {
                        let vname = v.name().map(|x| x.text().to_string()).unwrap_or_default();
                        // If it has a field list, we expand them, else just the variant name
                        if let Some(fl) = v.field_list() {
                            match fl {
                                ast::FieldList::RecordFieldList(rfl) => {
                                    let fields: Vec<String> = rfl.fields().map(|f| {
                                        let fname = f
                                            .name()
                                            .map(|n| n.text().to_string())
                                            .unwrap_or_default();
                                        let fty = f
                                            .ty()
                                            .map(|t| t.syntax().text().to_string())
                                            .unwrap_or_default();
                                        format!("{fname}: {fty}")
                                    }).collect();
                                    format!("{vname} {{ {} }}", fields.join(", "))
                                }
                                ast::FieldList::TupleFieldList(tfl) => {
                                    let fields: Vec<String> = tfl.fields().map(|f| {
                                        let fty = f.ty().map(|t| t.syntax().text().to_string()).unwrap_or_default();
                                        fty
                                    }).collect();
                                    format!("{vname}({})", fields.join(", "))
                                }
                            }
                        } else {
                            // no fields
                            vname
                        }
                    })
                    .collect();
                format!("{{\n    {},\n}}", items.join(",\n    "))
            } else {
                ";".to_string()
            }
        } else {
            "{ /* variants omitted */ }".to_string()
        };

        let core = format!(
            "{vis_str}enum {name}{generic_params_raw}{where_clause} {variants_text}"
        );

        let final_sig = format!("{doc_text}{core}");
        post_process_spacing(&final_sig)
    }
}

