            .unwrap_or_default();

        let where_clause_raw = self
            .where_clause()
            .map(|wc| wc.syntax().text().to_string())
            .unwrap_or_default();
        let where_clause = if where_clause_raw.is_empty() {
            "".to_string()
        } else {
            format!(" {}", where_clause_raw)
        };

        let visibility = self
            .visibility()
            .map(|v| format!("{} ", v.syntax().text()))
            .unwrap_or_default();

        // Always show the real aliased type, ignoring .fully_expand().
        // If there's no actual type node, we show "<unknown_aliased_type>" instead.
        let aliased_type = self
            .ty()
