            for assoc in item_list.assoc_items() {
                // Methods:
                if let Some(fn_ast) = ast::Fn::cast(assoc.syntax().clone()) {
                    let mut opts = opts.clone();
                    opts.set_add_semicolon(true);
                    // We can rely on our existing `GenerateSignature` for `ast::Fn`,
                    // or define a short signature ourselves. Here, we'll just call
                    // fn_ast.generate_signature() for consistency:
                    let method_sig = fn_ast.generate_signature_with_opts(&opts);
                    lines.push(method_sig);

                // Associated types:
                } else if let Some(type_ast) = ast::TypeAlias::cast(assoc.syntax().clone()) {
                    // For now, just push the raw text. You could parse out `type Foo;`
                    // or `type Foo = Something;` more elegantly if desired.
                    let raw_txt = type_ast.syntax().text().to_string();
                    lines.push(raw_txt);

                // Associated consts, etc.:
                } else if let Some(const_ast) = ast::Const::cast(assoc.syntax().clone()) {
                    let raw_txt = const_ast.syntax().text().to_string();
                    lines.push(raw_txt);
                }
            }
        }

        // 4) Format each line with indentation inside the trait braces:
        let mut items_str = String::new();
        for line in lines {
            for sub_line in line.lines() {
                items_str.push_str("    ");
                items_str.push_str(sub_line);
                items_str.push('\n');
            }
        }

        if items_str.trim().is_empty() {
            trace!("No associated items found in trait; returning empty braces");
            format!("{}trait {}{} {{}}", vis, name, generics)
        } else {
            trace!("Returning fully expanded trait signature with items");
            format!("{}trait {}{} {{\n{}}}", vis, name, generics, items_str)
        }
    }
}

impl GenerateSignature for ast::Fn {
    fn generate_signature_with_opts(&self, opts: &SignatureOptions) -> String {
        use tracing::{debug, trace};

        trace!("Generating signature for ast::Fn with opts: {:?}", opts);

        // 1) Possibly gather doc lines
        let doc_text = if *opts.include_docs() {
            extract_docs(&self.syntax())
                .map(|d| format!("{}\n", d))
                .unwrap_or_default()
        } else {
            "".to_string()
        };

        // 2) Gather visibility, async, etc.
        let vis_str = self
            .visibility()
            .map(|v| format!("{} ", v.syntax().text()))
            .unwrap_or_default();

        let async_str = if let Some(token) = self.async_token() {
            format!("{} ", token.text())
        } else {
            "".to_string()
        };

        let fn_keyword = "fn";
        let name_str = self
            .name()
            .map(|n| n.text().to_string())
            .unwrap_or_else(|| "<anon>".to_string());

        // 3) Generic params
        let generic_params = self
            .generic_param_list()
            .map(|gp| gp.syntax().text().to_string())
            .unwrap_or_default();

        // 4) Parameter list
        let mut param_texts = Vec::new();
        if let Some(plist) = self.param_list() {
            debug!(?plist, "Found param_list for fn");
            if let Some(sp) = plist.self_param() {
                let has_amp = sp.amp_token().is_some();  
                let has_mut = sp.mut_token().is_some();
                let lifetime_str = sp
                    .lifetime()
                    .map(|lt| lt.syntax().text().to_string())
                    .unwrap_or_default();

                let mut pieces = String::new();
                if has_amp {
                    pieces.push('&');
                    if !lifetime_str.is_empty() {
                        pieces.push_str(&lifetime_str);
                        pieces.push(' ');
                    }
                }
                if has_mut {
                    pieces.push_str("mut ");
                }
                pieces.push_str("self");
                param_texts.push(pieces.trim_end().to_string());
            }

            for param in plist.params() {
                if let Some(normal) = ast::Param::cast(param.syntax().clone()) {
                    let pat_str = normal
                        .pat()
                        .map(|p| p.syntax().text().to_string())
                        .unwrap_or_default();
                    let ty_str = normal
                        .ty()
                        .map(|t| t.syntax().text().to_string())
                        .unwrap_or_default();
                    if !pat_str.is_empty() && !ty_str.is_empty() {
                        param_texts.push(format!("{}: {}", pat_str, ty_str));
                    } else if !ty_str.is_empty() {
                        param_texts.push(ty_str);
                    } else if !pat_str.is_empty() {
                        param_texts.push(pat_str);
                    } else {
                        param_texts.push("<unknown_param>".to_string());
                    }
                } else {
                    param_texts.push("<unrecognized_param>".to_string());
                }
            }
        }
        let params_str = param_texts.join(", ");

        // 5) Return type
        let ret_str = if let Some(ret_type) = self.ret_type() {
            if let Some(ty_node) = ret_type.ty() {
                format!(" -> {}", ty_node.syntax().text())
            } else {
                "".to_string()
            }
        } else {
            "".to_string()
        };

        // 6) Where clause
        let where_str = if let Some(wc) = self.where_clause() {
            format!(" {}", wc.syntax().text())
        } else {
            "".to_string()
        };

        // 7) Build signature line ***WITHOUT*** appending braces.
        //    (We let CrateInterfaceItem<T> decide how to handle the body.)
        let raw_sig = format!(
            "{vis_str}{async_str}{fn_keyword} {name_str}{generic_params}({params_str}){ret_str}{where_str}"
        );

        let combined = match opts.add_semicolon() {
            true  => format!("{doc_text}{raw_sig};"),
            false => format!("{doc_text}{raw_sig}"),
        };

        post_process_spacing(&combined)
    }
}

impl GenerateSignature for ast::Struct {
    fn generate_signature_with_opts(&self, opts: &SignatureOptions) -> String {
        trace!("Generating signature for ast::Struct with opts: {:?}", opts);

        let doc_text = if *opts.include_docs() {
            extract_docs(&self.syntax())
                .map(|d| format!("{}\n", d))
                .unwrap_or_default()
        } else {
            "".to_string()
        };

        let vis_str = self
            .visibility()
            .map(|v| format!("{} ", v.syntax().text()))
            .unwrap_or_default();

        let name_str = self
            .name()
            .map(|n| n.to_string())
            .unwrap_or_else(|| "<unknown_struct>".to_string());

        let generic_params_raw = self
            .generic_param_list()
            .map(|g| g.syntax().text().to_string())
            .unwrap_or_default();

        let where_clause_raw = self
            .where_clause()
            .map(|wc| wc.syntax().text().to_string())
            .unwrap_or_default();
        let where_clause = if where_clause_raw.is_empty() {
            "".to_string()
        } else {
            format!(" {}", where_clause_raw)
        };

        // If fully_expand = true, let's gather actual fields:
        // If false, placeholders.
        let fields_text = if *opts.fully_expand() {
            if let Some(fl) = self.field_list() {
                match fl {
                    ast::FieldList::RecordFieldList(rfl) => {
                        let all_fields: Vec<String> = rfl
                            .fields()
                            .map(|field| {
                                let fname = field
                                    .name()
                                    .map(|n| n.text().to_string())
                                    .unwrap_or_default();
                                let fty = field
                                    .ty()
                                    .map(|t| t.syntax().text().to_string())
                                    .unwrap_or_default();
                                format!("    {}: {},", fname, fty)
                            })
                            .collect();
                        format!("{{\n{}\n}}", all_fields.join("\n"))
                    }
                    ast::FieldList::TupleFieldList(tfl) => {
                        let all_fields: Vec<String> = tfl
                            .fields()
                            .map(|field| {
                                let vis = field
                                    .visibility()
                                    .map(|v| format!("{} ", v.syntax().text()))
                                    .unwrap_or_default();
                                let fty = field
                                    .ty()
                                    .map(|t| t.syntax().text().to_string())
                                    .unwrap_or_default();
                                format!("    {}{},", vis, fty)
                            })
                            .collect();
                        format!("(\n{}\n);", all_fields.join("\n"))
                    }
                }
            } else {
                // no fields => e.g. `struct Foo;`
                ";".to_string()
            }
        } else {
            // minimal or placeholder approach
            "{ /* fields omitted */ }".to_string()
        };

        let core = format!(
            "{vis_str}struct {name_str}{generic_params_raw}{where_clause} {fields_text}"
        );

        let final_sig = format!("{doc_text}{core}");
        post_process_spacing(&final_sig)
    }
}

