pub trait GetVersionOfLocalDep {
    async fn version_of_local_dep(&self, dep_name: &str, dep_path: &str) -> Option<String>;
}

pub type LockVersionMap = BTreeMap<String, BTreeSet<SemverVersion>>;

/// If a local path is provided and the version is `"*"`, fetches the local version
/// and replaces the wildcard.
pub async fn replace_wildcard_version_with_local(inline_tab: &mut TeInlineTable, dep_name: &str, path_val: &str, root_cargo_toml: &dyn GetVersionOfLocalDep) {
    trace!(
        "replace_wildcard_version_with_local: dep_name='{}', path='{}'",
        dep_name,
        path_val
    );
    if let Some(local_ver) = root_cargo_toml.version_of_local_dep(dep_name, path_val).await {
        info!(
            "replace_wildcard_version_with_local: inserting local version='{}' for '{}'",
            local_ver, dep_name
        );
        inline_tab.insert("version", TeValue::from(local_ver));
    } else {
        debug!(
            "replace_wildcard_version_with_local: no local version found for '{}'",
            dep_name
        );
    }
}


pub fn pick_highest_version(crate_name: &str, lock_map: &BTreeMap<String, BTreeSet<SemverVersion>>) -> Option<SemverVersion> {
    let set = lock_map.get(crate_name)?;
    if set.len() > 1 {
        warn!(
            "pick_highest_version: crate '{}' has multiple versions in lock map: {:?}. Using the highest.",
            crate_name, set
        );
    }
    let highest = set.iter().max().unwrap();
    Some(highest.clone())
}


/// If a local path is provided but no version is present, attempts to fetch the version
/// from the local Cargo.toml and inserts it.
pub async fn insert_local_version_if_absent(inline_tab: &mut TeInlineTable, dep_name: &str, path_val: &str, root_cargo_toml: &dyn GetVersionOfLocalDep) {
    trace!(
        "insert_local_version_if_absent: dep_name='{}', path='{}'",
        dep_name,
        path_val
    );
    if let Some(local_ver) = root_cargo_toml.version_of_local_dep(dep_name, path_val).await {
        info!(
            "insert_local_version_if_absent: inserting local version='{}' for '{}'",
            local_ver, dep_name
        );
        inline_tab.insert("version", TeValue::from(local_ver));
    } else {
        debug!(
            "insert_local_version_if_absent: no local version found for '{}'",
            dep_name
        );
    }
}


pub async fn fix_nested_tables(root_item: &mut TeItem, lock_versions: &LockVersionMap, root_cargo_toml: &dyn GetVersionOfLocalDep) -> Result<(), CargoTomlError> {
    trace!("fix_nested_tables: start BFS over nested tables");
    let mut queue: std::collections::VecDeque<Vec<String>> = std::collections::VecDeque::new();
    queue.push_back(vec![]); // start at the top-level (root_item)

    while let Some(path) = queue.pop_front() {
        let maybe_item = get_item_mut_by_path(root_item, &path);
        let curr_item = match maybe_item {
            Some(i) => i,
            None => {
                continue; // Path might be invalid if something was removed or replaced
            }
        };

        // If it's a Table, gather subkeys and look for any "*dependencies" sub-table
        if let TeItem::Table(tbl) = curr_item {
            let subkeys: Vec<String> = tbl.iter().map(|(k, _)| k.to_string()).collect();

            // a) If subkey ends with "dependencies", pin them
            for subkey in &subkeys {
                if is_dependencies_key(subkey) {
                    if let Some(deps_item) = tbl.get_mut(subkey) {
                        if let TeItem::Table(dep_table) = deps_item {
                            pin_wildcard_dependencies_in_table(
                                dep_table,
                                lock_versions,
                                root_cargo_toml,
                            )
                            .await?;
                        }
                    }
                }
            }

            // b) Enqueue sub-items
            for subkey in &subkeys {
                let mut child_path = path.clone();
                child_path.push(subkey.clone());
                queue.push_back(child_path);
            }
        }
    }

    trace!("fix_nested_tables: end BFS");
    Ok(())
}


pub async fn pin_wildcard_inline_table_dependency(dep_item: &mut TeItem, dep_name: &str, lock_versions: &LockVersionMap, root_cargo_toml: &dyn GetVersionOfLocalDep) {
    trace!(
        "pin_wildcard_inline_table_dependency: dep_name='{}'",
        dep_name
    );
    if let TeItem::Value(TeValue::InlineTable(inline_tab)) = dep_item {
        let path_val = inline_tab
            .get("path")
            .and_then(|p| p.as_str())
            .map(String::from);
        let version_val = inline_tab
            .get("version")
            .and_then(|v| v.as_str())
            .map(String::from);

        match (path_val, version_val) {
            // If local path is present but no version item, insert local version if possible
            (Some(path_str), None) => {
                debug!(
                    "pin_wildcard_inline_table_dependency: local dep='{}', path='{}', no version present",
                    dep_name, path_str
                );
                insert_local_version_if_absent(inline_tab, dep_name, &path_str, root_cargo_toml).await;
            }
            // If local path is present and version is "*", replace wildcard with local version
            (Some(path_str), Some(v_str)) if v_str == "*" => {
                debug!(
                    "pin_wildcard_inline_table_dependency: local dep='{}', path='{}', wildcard version found",
                    dep_name, path_str
                );
                replace_wildcard_version_with_local(inline_tab, dep_name, &path_str, root_cargo_toml).await;
            }
            // If no path is present but version is "*", pin from lockfile
            (None, Some(v_str)) if v_str == "*" => {
                debug!(
                    "pin_wildcard_inline_table_dependency: dep='{}', no path, wildcard version found",
                    dep_name
                );
                pin_from_lock_or_warn(dep_item, dep_name, lock_versions);
            }
            // Otherwise, do nothing special
            _ => {
                trace!(
                    "pin_wildcard_inline_table_dependency: no wildcard action required for dep='{}'",
                    dep_name
                );
            }
        }
    }
    trace!(
        "pin_wildcard_inline_table_dependency: done dep_name='{}'",
        dep_name
    );
}


pub async fn pin_wildcards_in_doc(doc: &mut TeDocument, lock_versions: &LockVersionMap, root_cargo_toml: &dyn GetVersionOfLocalDep) -> Result<(), CargoTomlError> {
    // 1) top-level
    {
        let top_keys: Vec<String> = doc.as_table_mut().iter().map(|(k, _)| k.to_string()).collect();
        for key in top_keys {
            let item = doc.as_table_mut().get_mut(&key).unwrap();
            if is_dependencies_key(&key) {
                if let TeItem::Table(dep_tbl) = item {
                    pin_wildcard_dependencies_in_table(dep_tbl, lock_versions, root_cargo_toml)
                        .await?;
                }
            }
        }
    }

    // 2) nested
    fix_nested_tables(doc.as_item_mut(), lock_versions, root_cargo_toml).await?;
    Ok(())
}


/// Pins a wildcard sub-table dependency (e.g. `[dependencies.somecrate] version="*", path="..."`).
/// If the dependency has a local path, uses [`GetVersionOfLocalDep`] to retrieve the version.
/// Otherwise, falls back to the lockfile.
pub async fn pin_wildcard_table_dependency(dep_item: &mut TeItem, dep_name: &str, lock_versions: &LockVersionMap, root_cargo_toml: &dyn GetVersionOfLocalDep) {
    trace!(
        "pin_wildcard_table_dependency: dep_name='{}'",
        dep_name
    );
    if let TeItem::Table(sub_table) = dep_item {
        let path_item = sub_table.get("path");
        let version_item = sub_table.get("version");

        if let Some(path_val) = path_item.and_then(|v| v.as_str()) {
            debug!(
                "pin_wildcard_table_dependency: local dep='{}', path='{}'",
                dep_name, path_val
            );
            if version_item.is_none() {
                if let Some(local_ver) =
                    root_cargo_toml.version_of_local_dep(dep_name, path_val).await
                {
                    info!(
                        "pin_wildcard_table_dependency: inserting local version='{}' for '{}'",
                        local_ver, dep_name
                    );
                    sub_table.insert("version", TeItem::Value(TeValue::from(local_ver)));
                }
            } else if let Some(v_str) = version_item.and_then(|x| x.as_str()) {
                if v_str == "*" {
                    debug!(
                        "pin_wildcard_table_dependency: wildcard version found for '{}'",
                        dep_name
                    );
                    if let Some(local_ver) =
                        root_cargo_toml.version_of_local_dep(dep_name, path_val).await
                    {
                        info!(
                            "pin_wildcard_table_dependency: inserting local version='{}' for '{}'",
                            local_ver, dep_name
                        );
                        sub_table.insert("version", TeItem::Value(TeValue::from(local_ver)));
                    }
                }
            }
        } else {
            // no `path`, so fall back to lockfile if version is "*"
            if let Some(v_str) = version_item.and_then(|x| x.as_str()) {
                if v_str == "*" {
                    debug!(
                        "pin_wildcard_table_dependency: wildcard version found for '{}'",
                        dep_name
                    );
                    pin_from_lock_or_warn(dep_item, dep_name, lock_versions);
                }
            }
        }
    }
    trace!(
        "pin_wildcard_table_dependency: done dep_name='{}'",
        dep_name
    );
}


pub fn pin_from_lock_or_warn(dep_item: &mut TeItem, dep_name: &str, lock_versions: &LockVersionMap) {
    if let Some(new_ver) = pick_highest_version(dep_name, lock_versions) {
        let ver_str = new_ver.to_string();
        info!("Pinning wildcard '{}' => '{}'", dep_name, ver_str);
        match dep_item {
            TeItem::Value(TeValue::String { .. }) => {
                *dep_item = TeItem::Value(TeValue::from(ver_str));
            }
            TeItem::Value(TeValue::InlineTable(inline)) => {
                inline.insert("version", TeValue::from(ver_str));
            }
            TeItem::Table(tbl) => {
                tbl.insert("version", TeItem::Value(TeValue::from(ver_str)));
            }
            _ => {
                warn!("pin_from_lock_or_warn: item kind not recognized => cannot set version");
            }
        }
    } else {
        warn!(
            "pin_from_lock_or_warn: crate '{}' not in lock => leaving as '*'",
            dep_name
        );
    }
}


/// Pins a wildcard string dependency (e.g. `serde = "*"`) from the lockfile if its version is `*`.
/// If no entry is found in the lockfile, logs a warning and leaves it as `*`.
pub async fn pin_wildcard_string_dependency(dep_item: &mut TeItem, dep_name: &str, lock_versions: &LockVersionMap) {
    trace!(
        "pin_wildcard_string_dependency: dep_name='{}'",
        dep_name
    );
    let current_str = dep_item.as_str().unwrap_or("");
    if current_str == "*" {
        debug!("pin_wildcard_string_dependency: found wildcard for '{}'", dep_name);
        pin_from_lock_or_warn(dep_item, dep_name, lock_versions);
    }
    trace!(
        "pin_wildcard_string_dependency: done dep_name='{}'",
        dep_name
    );
}


/// Iterates over a TOML `TeTable` (i.e., `[dependencies]` or similar),
/// and pins any wildcard dependencies found. This ensures that workspace
/// dependencies do not remain `*` when building or releasing.
pub async fn pin_wildcard_dependencies_in_table(table: &mut TeTable, lock_versions: &LockVersionMap, root_cargo_toml: &dyn GetVersionOfLocalDep) -> Result<(), CargoTomlError> {
    trace!("pin_wildcard_dependencies_in_table: start");
    let dep_keys: Vec<String> = table.iter().map(|(k, _)| k.to_string()).collect();

    for dep_name in dep_keys {
        let dep_item = table.get_mut(&dep_name).expect("key must exist");
        match dep_item {
            TeItem::Value(TeValue::String { .. }) => {
                pin_wildcard_string_dependency(dep_item, &dep_name, lock_versions).await;
            }
            TeItem::Value(TeValue::InlineTable(_)) => {
                pin_wildcard_inline_table_dependency(
                    dep_item,
                    &dep_name,
                    lock_versions,
                    root_cargo_toml,
                )
                .await;
            }
            TeItem::Table(_) => {
                pin_wildcard_table_dependency(
                    dep_item,
                    &dep_name,
                    lock_versions,
                    root_cargo_toml,
                )
                .await;
            }
            _ => {
                trace!(
                    "pin_wildcard_dependencies_in_table: skipping dep='{}' => not string/inline/table",
                    dep_name
                );
            }
        }
    }

    trace!("pin_wildcard_dependencies_in_table: end");
    Ok(())
}


/// Checks if a table key ends with "dependencies"
pub fn is_dependencies_key(k: &str) -> bool {
    k.ends_with("dependencies")
}

impl<P, H> PinAllWildcardDependencies for Workspace<P, H> where for<'async_trait> P: From<PathBuf> + AsRef<Path> + Clone + Send + Sync + 'async_trait, for<'async_trait> H: CrateHandleInterface<P> + PinWildcardDependencies<Error = CrateError> + Send + Sync + 'async_trait {
    type Error = WorkspaceError;
    async fn pin_all_wildcard_dependencies(&mut self) -> Result<(), Self::Error> {
        info!("pin_all_wildcard_dependencies for Workspace at {:?}", self.as_ref());

        let lock_versions = match build_lock_versions(self).await {
            Ok(lv) => lv,
            Err(crate_err) => {
                return Err(WorkspaceError::CratePinFailed {
                    crate_path: self.as_ref().to_path_buf(),
                    source: Box::new(crate_err),
                });
            }
        };

        for arc_crate in self.crates() {
            let mut guard = arc_crate.lock().expect("expected to lock crate");
            debug!("pin_all_wildcard_dependencies: pinning a crate in the workspace...");
            guard
                .pin_wildcard_dependencies(&lock_versions)
                .await
                .map_err(|crate_err| WorkspaceError::CratePinFailed {
                    crate_path: guard.as_ref().to_path_buf(),
                    source: Box::new(crate_err),
                })?;
        }

        Ok(())
    }
}

impl PinWildcardDependencies for CargoToml {
    type Error = CargoTomlError;
    async fn pin_wildcard_dependencies(&mut self, lock_versions: &LockVersionMap) -> Result<(), Self::Error> {
        trace!("Reading original Cargo.toml from {:?}", self.as_ref());
        let mut doc = self.document_clone().await?;
        pin_wildcards_in_doc(&mut doc, lock_versions, self).await?;
        self.write_document_back(&doc).await?;
        info!("pin_wildcard_dependencies: updated {:?}", self.as_ref());
        Ok(())
    }
}

impl<P, H> PinAllWildcardDependencies for Workspace<P, H> where for<'async_trait> P: From<PathBuf> + AsRef<Path> + Clone + Send + Sync + 'async_trait, for<'async_trait> H: CrateHandleInterface<P> + PinWildcardDependencies<Error = CrateError> + AsyncTryFrom<PathBuf, Error = CrateError> // <-- IMPORTANT: we use AsyncTryFrom here + Send + Sync + 'async_trait {
    type Error = WorkspaceError;
    async fn pin_all_wildcard_dependencies(&mut self) -> Result<(), Self::Error> {
        info!(
            "pin_all_wildcard_dependencies: started for Workspace at path={:?}",
            self.as_ref()
        );

        // Build lock_versions first
        let lock_versions = match build_lock_versions(self).await {
            Ok(lv) => {
                trace!(
                    "pin_all_wildcard_dependencies: built lock_versions for workspace at path={:?}",
                    self.as_ref()
                );
                lv
            }
            Err(crate_err) => {
                error!(
                    "pin_all_wildcard_dependencies: build_lock_versions failed for {:?}: {:?}",
                    self.as_ref(),
                    crate_err
                );
                return Err(WorkspaceError::CratePinFailed {
                    crate_path: self.as_ref().to_path_buf(),
                    source: Box::new(crate_err),
                });
            }
        };

        // For each crate in this workspace, do not hold the MutexGuard across .await
        for arc_crate in self.crates() {
            let crate_path = {
                let guard = arc_crate.lock().await;
                let path = guard.as_ref().to_path_buf();
                debug!(
                    "pin_all_wildcard_dependencies: captured crate path={:?}, dropping guard",
                    path
                );
                path
            };

            // Construct a new H using AsyncTryFrom<PathBuf>
            let mut ephemeral = match <H as AsyncTryFrom<PathBuf>>::new(&crate_path).await {
                Ok(h) => {
                    trace!(
                        "pin_all_wildcard_dependencies: successfully built ephemeral handle for path={:?}",
                        crate_path
                    );
                    h
                }
                Err(e) => {
                    error!(
                        "pin_all_wildcard_dependencies: failed to build ephemeral handle for path={:?}: {:?}",
                        crate_path, e
                    );
                    return Err(WorkspaceError::CratePinFailed {
                        crate_path: crate_path.clone(),
                        source: Box::new(e),
                    });
                }
            };

            // Pin wildcard deps in that ephemeral handle
            if let Err(crate_err) = ephemeral.pin_wildcard_dependencies(&lock_versions).await {
                error!(
                    "pin_all_wildcard_dependencies: pin_wildcard_dependencies failed for path={:?}: {:?}",
                    crate_path, crate_err
                );
                return Err(WorkspaceError::CratePinFailed {
                    crate_path: crate_path.clone(),
                    source: Box::new(crate_err),
                });
            }

            // Overwrite the crate in memory
            {
                let mut guard = arc_crate.lock().await;
                *guard = ephemeral;
                debug!(
                    "pin_all_wildcard_dependencies: replaced crate data in memory for path={:?}",
                    crate_path
                );
            }
        }

        info!(
            "pin_all_wildcard_dependencies: completed for all crates in Workspace at path={:?}",
            self.as_ref()
        );
        Ok(())
    }
}

impl<T> GetVersionOfLocalDep for T where T: Send + Sync + AsRef<Path> {
    async fn version_of_local_dep(&self, dep_name: &str, dep_path: &str) -> Option<String> {
        let base_dir = self.as_ref().parent().unwrap_or_else(|| self.as_ref());
        // If `dep_path` is a directory, we should attempt to open `Cargo.toml` inside it
        // e.g. "../workspacer-config/Cargo.toml"
        let full_dir = base_dir.join(dep_path);
        let candidate_file = if full_dir.is_file() {
            // In case the snippet had path = "../somecrate/Cargo.toml", directly use it
            full_dir
        } else {
            // Typical Cargo style: path = "../somecrate", so look inside for "Cargo.toml"
            full_dir.join("Cargo.toml")
        };

        match CargoToml::new(&candidate_file).await {
            Ok(dep_ctoml) => match dep_ctoml.version() {
                Ok(ver) => {
                    info!(
                        "Found local version '{}' for dep='{}' at file={:?}",
                        ver, dep_name, candidate_file
                    );
                    Some(ver.to_string())
                }
                Err(e) => {
                    warn!(
                        "Could not parse local dep version for '{}': {:?}",
                        dep_name, e
                    );
                    None
                }
            },
            Err(e) => {
                warn!(
                    "Could not open local dep='{}' at path={:?}: {:?}",
                    dep_name, candidate_file, e
                );
                None
            }
        }
    }
}

impl PinWildcardDependencies for CrateHandle {
    type Error = CrateError;
    async fn pin_wildcard_dependencies(&mut self, lock_versions: &LockVersionMap) -> Result<(), CrateError> {
        trace!(
            "pin_wildcard_dependencies: starting for CrateHandle at path={:?}",
            self.as_ref()
        );

        // Store the Arc so it isn't dropped before we're done using guard
        let cargo_toml_arc = self.cargo_toml_direct();
        let cargo_toml_path = {
            let guard = cargo_toml_arc.lock().await;
            let path = guard.as_ref().to_path_buf();
            trace!("pin_wildcard_dependencies: got Cargo.toml path={:?}", path);
            path
        };

        // Load CargoToml from that path (no guard held across .await)
        let mut ephemeral = match CargoToml::new(&cargo_toml_path).await {
            Ok(ctoml) => {
                trace!(
                    "pin_wildcard_dependencies: successfully opened CargoToml at {:?}",
                    cargo_toml_path
                );
                ctoml
            }
            Err(e) => {
                error!(
                    "pin_wildcard_dependencies: cannot open CargoToml at {:?}: {:?}",
                    cargo_toml_path, e
                );
                return Err(e.into());
            }
        };

        // Perform async pinning on the ephemeral object
        ephemeral.pin_wildcard_dependencies(lock_versions).await?;
        trace!(
            "pin_wildcard_dependencies: ephemeral CargoToml pinned successfully at path={:?}",
            cargo_toml_path
        );

        // Now overwrite the in-memory CargoToml under lock
        {
            let mut guard = cargo_toml_arc.lock().await;
            *guard = ephemeral;
            debug!(
                "pin_wildcard_dependencies: replaced in-memory CargoToml at path={:?}",
                cargo_toml_path
            );
        }

        info!(
            "pin_wildcard_dependencies: finished for CrateHandle at path={:?}",
            self.as_ref()
        );
        Ok(())
    }
}

impl PinAllWildcardDependencies for CrateHandle {
    type Error = CrateError;
    async fn pin_all_wildcard_dependencies(&mut self) -> Result<(), Self::Error> {
        // 1) We need to build a LockVersionMap somehow.
        //    For single-crate, you can do the same build_lock_versions step
        //    that you do for a workspace, or a simpler "only read local lockfile"
        //    approach. Let's assume you have a function that does it:
        let lock_versions = build_lock_versions(self).await?;

        // 2) Then call the lower-level .pin_wildcard_dependencies():
        self.pin_wildcard_dependencies(&lock_versions).await
    }
}

