    info!("process_upward_node => start");
    trace!(
        "element.kind()={:?}, whitespace_newlines_since_last_nonws={}",
        element.kind(),
        state.whitespace_newlines_since_last_nonws()
    );

    let node = match element {
        NodeOrToken::Node(n) => {
            debug!("Got a Node => continuing");
            n
        }
        NodeOrToken::Token(_) => {
            error!("process_upward_node called with a Token => unreachable");
            return None;
        }
    };

    // If the node is the top-level file node, we skip it so that a single newline
    // between file start and our `fn` or `use` doesn't block comment collection.
    if node.kind() == SyntaxKind::SOURCE_FILE {
        info!("Skipping SOURCE_FILE node => keep climbing");
        state.set_whitespace_newlines_since_last_nonws(0);
        let ret = node.prev_sibling_or_token();
        debug!("process_upward_node => returning after skipping SOURCE_FILE => {:?}", ret.as_ref().map(|x| x.kind()));
        return ret;
    }

    let newlines = *state.whitespace_newlines_since_last_nonws();
    let result = if *state.found_comment() {
        // If we've started collecting, <2 newlines => stop; else skip
        if newlines < 2 {
            debug!("Found comment, node with <2 newlines => stop collecting => return None");
            None
        } else {
            debug!("Found comment, node with >=2 newlines => skip node & continue upward");
            state.set_whitespace_newlines_since_last_nonws(0);
            node.prev_sibling_or_token()
        }
    } else {
        // No comment yet => skip if >=2 newlines; else stop
        if newlines >= 2 {
            debug!("No comment yet, 2+ newlines => skip node & continue upward");
            state.set_whitespace_newlines_since_last_nonws(0);
            skip_upward_node_with_whitespace(Some(NodeOrToken::Node(node)))
        } else {
            debug!("Node with <2 newlines => stop => no comments found yet => return None");
            None
        }
    };

    debug!(
        "process_upward_node => end; returning: {}",
        if result.is_none() {
            "None".to_string()
        } else {
            format!("Some({:?})", result.as_ref().unwrap().kind())
        }
    );
    info!("process_upward_node => done");
    result
}


/// Detects a same-line trailing `// comment` starting just after offset `pos`
/// (e.g. after the semicolon). If found, returns `(comment_text, total_length)`
/// so we can store that comment text and expand the removal range.
/// If none found, returns None.
pub fn detect_trailing_comment_same_line(old_text: &str, pos: usize) -> Option<(String, usize)> {
    info!("detect_trailing_comment_same_line => start; pos={}", pos);
    if pos >= old_text.len() {
        debug!("Position >= old_text.len() => no trailing comment");
        return None;
    }

    // We'll scan up to the next newline or end-of-file
    let line_end = match old_text[pos..].find('\n') {
        Some(rel) => pos + rel,
        None => old_text.len(),
    };

    // The substring from pos..line_end is the remainder on that line
    let candidate = &old_text[pos..line_end];
    debug!("Same-line candidate is {:?}", candidate);

    // We'll skip any leading spaces/tabs after the semicolon
    let trimmed_start = candidate.find(|c: char| !c.is_whitespace()).unwrap_or(candidate.len());
    let check_pos = pos + trimmed_start;
    if check_pos + 2 <= line_end && &old_text[check_pos..check_pos + 2] == "//" {
        // The comment is from check_pos..line_end
        let comment = old_text[check_pos..line_end].to_string();
        // The total length covers from pos..line_end
        let total_len = line_end - pos;
        info!("detect_trailing_comment_same_line => found comment => {:?}", comment);
        Some((comment, total_len))
    } else {
        debug!("No trailing '//' found => returning None");
        None
    }
}


pub fn process_other_token(tok: SyntaxToken, text: String, state: &mut GatherCommentsState) -> Option<NodeOrToken<SyntaxNode, SyntaxToken>> {
    info!("process_other_token => start");
    trace!(
        "kind={:?}, newlines={}, text length={}",
        tok.kind(),
        state.whitespace_newlines_since_last_nonws(),
        text.len()
    );

    let newlines = *state.whitespace_newlines_since_last_nonws();
    let result = if *state.found_comment() {
        // Already collecting => <2 newlines => stop, else skip
        if newlines < 2 {
            debug!("Already found comment => <2 newlines => stop collecting => None");
            None
        } else {
            debug!("Already found comment => >=2 newlines => skip & continue => resetting to 0");
            state.set_whitespace_newlines_since_last_nonws(0);
            tok.prev_sibling_or_token()
        }
    } else {
        // No comment yet => skip if >=2 newlines, else stop
        if newlines >= 2 {
            debug!("No comment yet => >=2 newlines => skip token & continue => resetting to 0");
            state.set_whitespace_newlines_since_last_nonws(0);
            tok.prev_sibling_or_token()
        } else {
            debug!("No comment yet => <2 newlines => stop => None");
            None
        }
    };

    debug!(
        "process_other_token => end; returning {}",
        if result.is_none() {
            "None".to_string()
        } else {
            format!("Some({:?})", result.as_ref().unwrap().kind())
        }
    );
    info!("process_other_token => done");
    result
}


pub fn scan_preceding_tokens_for_comments(start_node: &SyntaxNode) -> Vec<String> {
    info!(
        "scan_preceding_tokens_for_comments => node.kind()={:?}",
        start_node.kind()
    );

    trace!("Trying gather_sibling_comments_above first");
    let sibling_comments = gather_sibling_comments_above(start_node);
    if !sibling_comments.is_empty() {
        debug!(
            "Found {} sibling comment lines => returning early",
            sibling_comments.len()
        );
        return sibling_comments;
    }

    trace!("No sibling comments => calling gather_token_comments_above");
    let token_comments = gather_token_comments_above(start_node);
    debug!("Found {} token-based comment lines", token_comments.len());
    token_comments
}


pub fn fallback_scan_node_text(node: &SyntaxNode) -> Vec<String> {
    info!(
        "fallback_scan_node_text => start; node.kind()={:?}",
        node.kind()
    );
    let node_text = node.text().to_string();
    trace!("node_text length={}", node_text.len());

    let mut results = Vec::new();
    for line in node_text.lines() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("//") {
            let line = if trimmed.ends_with('\n') {
                trimmed.to_string()
            } else {
                format!("{}\n", trimmed)
            };
            trace!("Found line-comment => {:?}", line);
            results.push(line);
        } else if trimmed.is_empty() {
            warn!("Blank line => stopping fallback scan");
            break;
        } else {
            debug!("Non-comment line => stopping fallback scan");
            break;
        }
    }

    debug!("fallback_scan_node_text => returning {} lines", results.len());
    info!("fallback_scan_node_text => done");
    results
}


/**
Updated build_new_use_lines to accept the trailing_comments map as a third parameter.
If your existing tests only pass two arguments, just add `&BTreeMap::new()` as the third.
*/
pub fn build_new_use_lines(grouped_map: &BTreeMap<(String, String), BTreeSet<String>>, comment_map: &BTreeMap<(String, String), Vec<String>>, trailing_comments: &BTreeMap<(String, String, String), String>) -> String {
    info!("build_new_use_lines => start");
    debug!(
        "grouped_map.len()={}, comment_map.len()={}, trailing_comments.len()={}",
        grouped_map.len(),
        comment_map.len(),
        trailing_comments.len()
    );

    // If map is empty => return "\n"
    if grouped_map.is_empty() {
        debug!("grouped_map empty => returning single newline");
        info!("build_new_use_lines => done");
        return "\n".to_string();
    }

    // Convert to a vector of (vis, prefix, finals)
    let mut entries: Vec<(String, String, Vec<String>)> = Vec::new();
    for ((vis, prefix), set_of_finals) in grouped_map {
        let mut finals_vec: Vec<_> = set_of_finals.iter().cloned().collect();
        finals_vec.sort();
        entries.push((vis.clone(), prefix.clone(), finals_vec));
    }

    // Sort them by prefix, then vis (or in the order you want)
    entries.sort_by(|(va, pa, _), (vb, pb, _)|
        pa.cmp(pb).then_with(|| va.cmp(vb))
    );

    let mut new_use_lines = Vec::new();

    for (vis, prefix, finals_vec) in entries {
        // If we have leading comments in comment_map => add them now
        if let Some(cmts) = comment_map.get(&(vis.clone(), prefix.clone())) {
            for c in cmts {
                new_use_lines.push(c.clone());
            }
        }

        // Build the "use" line(s)
        if finals_vec.len() > 1 {
            // multiple finals => brace them
            let joined = finals_vec.join(", ");
            if prefix.is_empty() {
                new_use_lines.push(format!("{} use {};", vis, joined));
            } else {
                new_use_lines.push(format!("{} use {}::{{{}}};", vis, prefix, joined));
            }
        } else if finals_vec.len() == 1 {
            // single final => check trailing_comments
            let single_final = &finals_vec[0];
            // generate e.g. "pub use crate::foo::Bar;"
            let base_line = if prefix.is_empty() {
                format!("{} use {};", vis, single_final)
            } else {
                format!("{} use {}::{};", vis, prefix, single_final)
            };

            // see if there's a trailing comment
            let triple_key = (vis.clone(), prefix.clone(), single_final.clone());
            if let Some(tr_comment) = trailing_comments.get(&triple_key) {
                // e.g. => "pub use crate::foo::Bar; // trailing comment"
                // we'll put a space if comment doesn't start with "//"
                // or if it does, just put a space
                if tr_comment.starts_with("//") {
                    new_use_lines.push(format!("{} {}", base_line, tr_comment));
                } else {
                    new_use_lines.push(format!("{} //{}", base_line, tr_comment));
                }
            } else {
                // no trailing comment => push the base line
                new_use_lines.push(base_line);
            }
        } else {
            // finals_vec is empty => edge case => skip or do something else
        }
    }

    // trailing newline
    new_use_lines.push(String::new());
    let block = new_use_lines.join("\n");
    debug!(
        "build_new_use_lines => final block length={}",
        block.len()
    );
    info!("build_new_use_lines => done");
    block
}


/// Skip exactly one node plus any *preceding* whitespace tokens, returning
/// the next `NodeOrToken` above. This is used when:
/// - We see a blank line
/// - The next non-whitespace is a node (not a comment)
/// - We want to “skip” that node and keep climbing upward.
///
/// We also skip any whitespace tokens directly above that node.
pub fn skip_node_plus_trailing_whitespace(mut cur: Option<NodeOrToken<SyntaxNode, SyntaxToken>>) -> Option<NodeOrToken<SyntaxNode, SyntaxToken>> {
    // First skip the node itself
    if let Some(NodeOrToken::Node(_)) = cur {
        cur = cur.and_then(|x| x.prev_sibling_or_token());
    }
    // Then skip any whitespace tokens above that node
    while let Some(n_or_t) = &cur {
        if let NodeOrToken::Token(tok) = n_or_t {
            if tok.kind() == SyntaxKind::WHITESPACE {
                cur = tok.prev_sibling_or_token();
                continue;
            }
        }
        // If it's not a whitespace token, break
        break;
    }
    cur
}


pub fn gather_token_comments_above(start_node: &SyntaxNode) -> Vec<String> {
    info!(
        "gather_token_comments_above => start; node.kind()={:?}",
        start_node.kind()
    );

    let tokens: Vec<SyntaxElement> = start_node.children_with_tokens().collect();
    if tokens.is_empty() {
        debug!("No tokens => returning empty");
        info!("gather_token_comments_above => done => returning empty");
        return Vec::new();
    }

    let mut collected = Vec::new();
    let mut found_comment = false;
    let mut whitespace_newlines_since_last_nonws = 0;

    for elem in &tokens {
        match elem.kind() {
            SyntaxKind::COMMENT => {
                let txt = elem.to_string();
                let line = if txt.ends_with('\n') {
                    txt
                } else {
                    format!("{}\n", txt)
                };
                trace!("Found COMMENT => line={:?}", line);
                collected.push(line);
                found_comment = true;
                whitespace_newlines_since_last_nonws = 0;
            }
            SyntaxKind::WHITESPACE => {
                let txt_no_cr = elem.to_string().replace('\r', "");
                if let Some(embedded) = try_extract_embedded_comment_in_whitespace(&txt_no_cr) {
                    trace!("Found {} embedded comments in whitespace", embedded.len());
                    for line in embedded {
                        let forced = if line.ends_with('\n') {
                            line
                        } else {
                            format!("{}\n", line)
                        };
                        collected.push(forced);
                    }
                    found_comment = true;
                    whitespace_newlines_since_last_nonws = 0;
                } else {
                    let newline_count = txt_no_cr.matches('\n').count();
                    debug!(
                        "WHITESPACE => newline_count={}, found_comment={}",
                        newline_count, found_comment
                    );
                    if found_comment {
                        if newline_count >= 2 {
                            warn!("Blank line after comment => stopping collection");
                            break;
                        }
                        whitespace_newlines_since_last_nonws += newline_count;
                    } else {
                        if newline_count >= 2 {
                            warn!("Blank line blocks => returning empty immediately");
                            info!("gather_token_comments_above => done => returning empty");
                            return Vec::new();
                        } else {
                            whitespace_newlines_since_last_nonws += newline_count;
                        }
                    }
                }
            }
            other_kind => {
                trace!(
                    "Encountered non-comment token => kind={:?}, ws_newlines={}",
                    other_kind,
                    whitespace_newlines_since_last_nonws
                );
                if whitespace_newlines_since_last_nonws < 2 {
                    debug!("Non-comment token with <2 newlines => stopping");
                    break;
                } else {
                    debug!("Non-comment token with >=2 newlines => skip & continue");
                    whitespace_newlines_since_last_nonws = 0;
                }
            }
        }
    }

    debug!(
        "gather_token_comments_above => collected {} lines => returning",
        collected.len()
    );
    info!("gather_token_comments_above => done");
    collected
}


pub fn process_whitespace_token(tok: SyntaxToken, text: String, state: &mut GatherCommentsState) -> Option<NodeOrToken<SyntaxNode, SyntaxToken>> {
    info!(
        "process_whitespace_token => start; text length={}, found_comment={}",
        text.len(),
        state.found_comment()
    );

    // Normalize \r\n into \n so single newlines are counted consistently.
    let text_no_cr = text.replace('\r', "");
    let newline_count = text_no_cr.matches('\n').count();
    trace!(
        "Calculated newline_count={}, found_comment={}",
        newline_count,
        state.found_comment()
    );

    // We keep single newlines to keep climbing so we can detect any "directly above" comment 
    // that might be behind this whitespace.  The user’s “tests” want that behavior.
    let result = if *state.found_comment() {
        if newline_count >= 2 {
            warn!("Blank line after collected comment => stop => returning None");
            None
        } else {
            debug!(
                "Already have comment => single newline => keep climbing => +{}",
                newline_count
            );
            *state.whitespace_newlines_since_last_nonws_mut() += newline_count;
            tok.prev_sibling_or_token()
        }
    } else {
        if newline_count >= 2 {
            warn!("No comment yet => blank line => block => returning None");
            None
        } else {
            debug!(
                "No comment => single newline => keep climbing => +{}",
                newline_count
            );
            *state.whitespace_newlines_since_last_nonws_mut() += newline_count;
            tok.prev_sibling_or_token()
        }
    };

    debug!(
        "process_whitespace_token => end; returning: {}",
        if result.is_none() {
            "None".to_string()
        } else {
            format!("Some({:?})", result.as_ref().unwrap().kind())
        }
    );
    info!("process_whitespace_token => done");
    result
}


pub fn skip_upward_node_with_whitespace(mut cur: Option<NodeOrToken<SyntaxNode, SyntaxToken>>) -> Option<NodeOrToken<SyntaxNode, SyntaxToken>> {
    info!("skip_upward_node_with_whitespace => entered");
    if let Some(ref e) = cur {
        debug!("Starting from element kind={:?}", e.kind());
    } else {
        debug!("Starting from None");
    }

    // First skip the node itself
    if let Some(NodeOrToken::Node(_)) = cur {
        trace!("Skipping the node");
        cur = cur.and_then(|x| x.prev_sibling_or_token());
    }

    // Then skip any whitespace tokens above that node
    while let Some(n_or_t) = &cur {
        trace!("Examining preceding sibling/token => kind={:?}", n_or_t.kind());
        if let NodeOrToken::Token(tok) = n_or_t {
            if tok.kind() == SyntaxKind::WHITESPACE {
                debug!("Skipping whitespace token");
                cur = tok.prev_sibling_or_token();
                continue;
            }
        }
        break;
    }

    debug!("Final element after skipping => {:?}", cur.as_ref().map(|x| x.kind()));
    info!("skip_upward_node_with_whitespace => done");
    cur
}


pub fn gather_leading_token_comments(node: &SyntaxNode) -> Vec<String> {
    info!(
        "gather_leading_token_comments => start; node.kind()={:?}",
        node.kind()
    );

    let tokens: Vec<SyntaxElement> = node.children_with_tokens().collect();
    if tokens.is_empty() {
        debug!("No tokens => returning empty Vec");
        info!("gather_leading_token_comments => done => returning empty");
        return Vec::new();
    }

    let mut collected = Vec::new();
    let mut found_comment = false;
    let mut whitespace_newlines_since_last_nonws = 0;

    for elem in &tokens {
        match elem.kind() {
            SyntaxKind::COMMENT => {
                // Found a comment => store it
                let txt = elem.to_string();
                let line = if txt.ends_with('\n') {
                    txt
                } else {
                    format!("{}\n", txt)
                };
                trace!("Found COMMENT => line={:?}", line);
                collected.push(line);
                found_comment = true;
                whitespace_newlines_since_last_nonws = 0;
            }
            SyntaxKind::WHITESPACE => {
                let txt_no_cr = elem.to_string().replace('\r', "");
                // Check for embedded `//` lines
                if let Some(comment_lines) = try_extract_embedded_comment_in_whitespace(&txt_no_cr) {
                    trace!("Found {} embedded comments in whitespace", comment_lines.len());
                    for cmt in comment_lines {
                        let forced_newline = if cmt.ends_with('\n') {
                            cmt
                        } else {
                            format!("{}\n", cmt)
                        };
                        collected.push(forced_newline);
                    }
                    found_comment = true;
                    whitespace_newlines_since_last_nonws = 0;
                } else {
                    let newline_count = txt_no_cr.matches('\n').count();
                    debug!(
                        "WHITESPACE => newline_count={}, found_comment={}",
                        newline_count, found_comment
                    );
                    if found_comment {
                        // Once we've started collecting comments, 2+ newlines => blank line => stop
                        if newline_count >= 2 {
                            warn!("Blank line after comment => stopping");
                            break;
                        }
                        whitespace_newlines_since_last_nonws += newline_count;
                    } else {
                        // If no comment yet => 2+ newlines => block => return empty
                        if newline_count >= 2 {
                            warn!("Blank line => no comment yet => returning empty");
                            info!("gather_leading_token_comments => done => returning empty");
                            return Vec::new();
                        }
                        whitespace_newlines_since_last_nonws += newline_count;
                    }
                }
            }
            other => {
                trace!(
                    "Found non-comment token => kind={:?}, ws_newlines={}",
                    other,
                    whitespace_newlines_since_last_nonws
                );
                // If we've found comments already, then <2 newlines => stop collecting
                // If we haven't found any comment, <2 newlines => also stop
                if whitespace_newlines_since_last_nonws < 2 {
                    debug!("Non-comment token with <2 newlines => stop collecting");
                    break;
                } else {
                    debug!("Non-comment token with >=2 newlines => skip & continue");
                    whitespace_newlines_since_last_nonws = 0;
                }
            }
        }
    }

    debug!(
        "gather_leading_token_comments => returning {} collected lines",
        collected.len()
    );
    info!("gather_leading_token_comments => done");
    collected
}


pub fn try_extract_embedded_comment_in_whitespace(ws_text: &str) -> Option<Vec<String>> {
    // If the text doesn't contain "//", no need to parse further
    if !ws_text.contains("//") {
        return None;
    }
    let mut lines = Vec::new();
    for raw_line in ws_text.lines() {
        let trimmed = raw_line.trim_start();
        if trimmed.starts_with("//") {
            lines.push(trimmed.to_owned());
        }
    }
    if lines.is_empty() {
        None
    } else {
        Some(lines)
    }
}


pub fn dispatch_token_by_kind(tok: SyntaxToken, state: &mut GatherCommentsState) -> Option<NodeOrToken<SyntaxNode, SyntaxToken>> {
    info!("dispatch_token_by_kind => start");
    use SyntaxKind::*;
    let text = tok.text().to_string();
    debug!("Token kind={:?}, text.len()={}", tok.kind(), text.len());

    let result = match tok.kind() {
        COMMENT => {
            debug!("COMMENT => collect_comment_token");
            collect_comment_token(tok, text, state)
        }
        WHITESPACE => {
            debug!("WHITESPACE => process_whitespace_token");
            process_whitespace_token(tok, text, state)
        }
        _ => {
            debug!("OTHER => process_other_token");
            process_other_token(tok, text, state)
        }
    };

    debug!(
        "dispatch_token_by_kind => done; returning {}",
        if result.is_none() {
            "None".to_string()
        } else {
            format!("Some({:?})", result.as_ref().unwrap().kind())
        }
    );
    info!("dispatch_token_by_kind => done");
    result
}


/**
The key fix: remove the `trim_start()` on the remainder.  
We want to preserve leading blank lines in the remainder so that if 
there was a blank line after some block comment, it stays in the final output.
*/
pub fn combine_new_uses_with_remainder(new_uses_block: &str, remainder: &str) -> String {
    info!("combine_new_uses_with_remainder => start");
    debug!(
        "new_uses_block.len()={}, remainder.len()={}",
        new_uses_block.len(),
        remainder.len()
    );

    let trimmed_new = new_uses_block.trim();
    if trimmed_new.is_empty() {
        debug!("No new uses => returning remainder as is");
        info!("combine_new_uses_with_remainder => done => returning remainder");
        // Keep remainder fully intact
        return remainder.to_string();
    } else {
        debug!("Some new uses => combining with remainder");
        // Instead of trimming the remainder’s start, 
        // keep it as-is so any leading blank lines remain.
        let combined = format!("{}\n{}", trimmed_new, remainder);
        info!("combine_new_uses_with_remainder => done => returning combined");
        combined
    }
}


pub fn gather_sibling_comments_above(node: &SyntaxNode) -> Vec<String> {
    info!(
        "gather_sibling_comments_above => start; node.kind()={:?}",
        node.kind()
    );

    let Some(parent) = node.parent() else {
        debug!("No parent => returning empty Vec");
        info!("gather_sibling_comments_above => done => returning empty");
        return Vec::new();
    };

    // Collect the parent's children, in order
    let siblings: Vec<SyntaxElement> = parent.children_with_tokens().collect();

    // Find the index of our node among siblings
    let node_elem = SyntaxElement::Node(node.clone());
    let Some(idx) = siblings.iter().position(|elem| *elem == node_elem) else {
        debug!("Node not found among parent's children => returning empty Vec");
        info!("gather_sibling_comments_above => done => returning empty");
        return Vec::new();
    };

    // If idx == 0 => no preceding siblings => fallback to the node’s own leading-token approach
    if idx == 0 {
        trace!("No preceding siblings => fallback to gather_leading_token_comments");
        let fallback = gather_leading_token_comments(node);
        debug!(
            "gather_sibling_comments_above => returning fallback with {} lines",
            fallback.len()
        );
        info!("gather_sibling_comments_above => done");
        return fallback;
    }

    let mut collected = Vec::new();
    let mut found_comment = false;
    let mut whitespace_newlines_since_last_nonws = 0;

    // Iterate backwards from the sibling *just before* this node, up to 0
    for elem in siblings[..idx].iter().rev() {
        match elem.kind() {
            SyntaxKind::COMMENT => {
                // Insert the comment at the front
                let txt = elem.to_string();
                let line = if txt.ends_with('\n') {
                    txt
                } else {
                    format!("{}\n", txt)
                };
                trace!("Found COMMENT => line={:?}", line);
                collected.insert(0, line);
                found_comment = true;
                whitespace_newlines_since_last_nonws = 0;
            }
            SyntaxKind::WHITESPACE => {
                let txt_no_cr = elem.to_string().replace('\r', "");
                // Check if there are embedded `//` lines in the whitespace
                if let Some(comment_lines) = try_extract_embedded_comment_in_whitespace(&txt_no_cr) {
                    trace!("Found {} embedded comments inside whitespace", comment_lines.len());
                    for line in comment_lines {
                        let forced_newline = if line.ends_with('\n') {
                            line
                        } else {
                            format!("{}\n", line)
                        };
                        collected.insert(0, forced_newline);
                    }
                    found_comment = true;
                    whitespace_newlines_since_last_nonws = 0;
                } else {
                    let newline_count = txt_no_cr.matches('\n').count();
                    debug!(
                        "WHITESPACE => newline_count={}, found_comment={}",
                        newline_count, found_comment
                    );
                    if found_comment {
                        // If we've already got comments, 2+ newlines => blank line => stop scanning
                        if newline_count >= 2 {
                            warn!("Blank line after comment => stopping");
                            break;
                        }
                        whitespace_newlines_since_last_nonws += newline_count;
                    } else {
                        // If we haven't found any comment yet and we see 2+ newlines => block
                        if newline_count >= 2 {
                            warn!("Blank line => no comment yet => returning empty Vec");
                            info!("gather_sibling_comments_above => done => returning empty");
                            return Vec::new();
                        } else {
                            whitespace_newlines_since_last_nonws += newline_count;
                        }
                    }
                }
            }
            other => {
                // Non-comment sibling: if we haven't accumulated 2+ newlines, that means we stop.
                trace!(
                    "Found non-comment sibling => kind={:?}, ws_newlines={}",
                    other,
                    whitespace_newlines_since_last_nonws
                );
                if whitespace_newlines_since_last_nonws < 2 {
                    debug!("Non-comment sibling with <2 newlines => stop");
                    break;
                } else {
                    debug!("Non-comment sibling with >=2 newlines => skip & continue");
                    whitespace_newlines_since_last_nonws = 0;
                }
            }
        }
    }

    // If we found nothing among siblings, let's see if there's a comment in the node’s own leading tokens
    if collected.is_empty() {
        debug!("No sibling comments found => fallback to gather_leading_token_comments");
        let fallback = gather_leading_token_comments(node);
        if !fallback.is_empty() {
            info!(
                "gather_sibling_comments_above => done => returning fallback with {} lines",
                fallback.len()
            );
            return fallback;
        }
    }

    debug!(
        "gather_sibling_comments_above => returning {} collected lines",
        collected.len()
    );
    info!("gather_sibling_comments_above => done");
    collected
}


pub fn sort_and_format_imports_in_text(old_text: &str) -> Result<String, SortAndFormatImportsError> {
    info!("Entering sort_and_format_imports_in_text");
    debug!("Input text length is {}", old_text.len());

    // 1) Parse
    trace!("About to parse/validate syntax");
    let file = match parse_and_validate_syntax(old_text) {
        Ok(f) => {
            debug!("parse_and_validate_syntax succeeded");
            f
        }
        Err(e) => {
            error!("parse_and_validate_syntax failed => {:?}", e);
            return Err(e);
        }
    };

    // 2) Gather use items
    debug!("Gathering use items from file & old_text");
    let uses_data = gather_use_items(&file, old_text);
    trace!("Collected {} use items", uses_data.len());

    // 3) Group them => now returns (grouped_map, comment_map, trailing_comments)
    debug!("Grouping and sorting use items now");
    let (grouped_map, comment_map, trailing_comments) = group_and_sort_uses(&uses_data);
    trace!(
        "grouped_map.len()={}, comment_map.len()={}, trailing_comments.len()={}",
        grouped_map.len(),
        comment_map.len(),
        trailing_comments.len()
    );

    // 4) Build new use lines
    debug!("Building new use lines...");
    let new_uses_block = build_new_use_lines(&grouped_map, &comment_map, &trailing_comments);
    trace!("New uses block:\n{}", new_uses_block);

    // 5) Remove old uses
    debug!("Removing old use statements from the original text");
    let remainder = remove_old_use_statements(&uses_data, old_text);

    // 6) Combine
    debug!("Combining new uses block with remainder");
    let final_text = combine_new_uses_with_remainder(&new_uses_block, &remainder);

    info!(
        "Finished sort_and_format_imports_in_text => final_text length is {}",
        final_text.len()
    );
    Ok(final_text)
}


pub fn parse_and_validate_syntax(old_text: &str) -> Result<SourceFile, SortAndFormatImportsError> {
    info!(
        "parse_and_validate_syntax => start; old_text length={}",
        old_text.len()
    );
    let parse = SourceFile::parse(old_text, Edition::Edition2021);
    let file = parse.tree();

    if !parse.errors().is_empty() {
        error!(
            "parse_and_validate_syntax => errors found => count={}",
            parse.errors().len()
        );
        let joined = parse
            .errors()
            .iter()
            .map(|e| e.to_string())
            .collect::<Vec<_>>()
            .join(", ");
        return Err(SortAndFormatImportsError::RaApParseError {
            parse_errors: joined,
        });
    }

    debug!("parse_and_validate_syntax => no parse errors => returning Ok(file)");
    info!("parse_and_validate_syntax => done");
    Ok(file)
}


pub fn collect_comment_token(tok: SyntaxToken, text: String, state: &mut GatherCommentsState) -> Option<NodeOrToken<SyntaxNode, SyntaxToken>> {
    info!("collect_comment_token => start");
    let line = if text.ends_with('\n') {
        text
    } else {
        format!("{}\n", text)
    };
    debug!("Adding comment line => {:?}", line);
    state.collected_mut().insert(0, line);
    state.set_found_comment(true);
    state.set_whitespace_newlines_since_last_nonws(0);

    let ret = tok.prev_sibling_or_token();
    trace!("collect_comment_token => returning {:?}", ret.as_ref().map(|x| x.kind()));
    info!("collect_comment_token => done");
    ret
}


pub fn remove_old_use_statements(uses_data: &[UseItemInfo], old_text: &str) -> String {
    info!("remove_old_use_statements => start");
    debug!("old_text length={}", old_text.len());
    debug!("use_data count={}", uses_data.len());

    let mut out = String::new();
    let mut start_pos = 0usize;

    for ud in uses_data {
        trace!("Removing range {}..{} for path_list={:?}", ud.range_start(), ud.range_end(), ud.path_list());
        let s = *ud.range_start();
        let e = *ud.range_end();
        if s > start_pos {
            out.push_str(&old_text[start_pos..s]);
        }
        start_pos = e;
    }

    if start_pos < old_text.len() {
        out.push_str(&old_text[start_pos..]);
    }

    debug!(
        "remove_old_use_statements => returning text length={}",
        out.len()
    );
    info!("remove_old_use_statements => done");
    out
}


pub fn dissect_use_statement(line: &str) -> Option<(String, String, String)> {
    info!("dissect_use_statement => start");
    let trimmed = line.trim();
    trace!("trimmed input={:?}", trimmed);

    let use_idx = match trimmed.find("use ") {
        Some(idx) => idx,
        None => {
            debug!("No 'use ' substring found => returning None");
            info!("dissect_use_statement => done => None");
            return None;
        }
    };

    // Ensure the character before "use " is start-of-line or whitespace
    if use_idx > 0 {
        let prev_char = trimmed.chars().nth(use_idx - 1)?;
        if !prev_char.is_whitespace() {
            debug!(
                "Character before 'use ' is {:?}, not whitespace => returning None",
                prev_char
            );
            info!("dissect_use_statement => done => None");
            return None;
        }
    }

    let prefix = &trimmed[..use_idx].trim();
    let after_use = &trimmed[use_idx + 4..];
    let after_use = after_use.trim_end_matches(';').trim();
    debug!(
        "Parsed => prefix={:?}, 'use', path_list={:?}",
        prefix, after_use
    );

    info!("dissect_use_statement => done => returning Some");
    Some((prefix.to_string(), "use".to_string(), after_use.to_string()))
}


/**
Now we always return three items: (grouped_map, comment_map, trailing_comments).
If you have code/tests that only care about grouped_map & comment_map,
just destructure as: 
let (grouped_map, comment_map, _trailing) = group_and_sort_uses(...);
ignoring the trailing_comments value.
*/
pub fn group_and_sort_uses(uses_data: &[UseItemInfo]) -> (
    BTreeMap<(String, String), BTreeSet<String>>,
    BTreeMap<(String, String), Vec<String>>,
    BTreeMap<(String, String, String), String>, // trailing_comments
) {
    info!("group_and_sort_uses => start");
    debug!("Received uses_data with length={}", uses_data.len());

    let mut grouped_map = BTreeMap::new();
    let mut comment_map = BTreeMap::new();
    let mut trailing_comments = BTreeMap::new();

    for ud in uses_data {
        trace!(
            "Processing UseItemInfo => vis={:?}, path_list={:?}, trailing_comment={:?}",
            ud.visibility(),
            ud.path_list(),
            ud.trailing_comment()
        );

        let (prefix, finals) = split_path_into_prefix_and_final(ud.path_list());
        let key = (ud.visibility().clone(), prefix.clone());

        // 1) Insert leading comments into comment_map
        comment_map
            .entry(key.clone())
            .or_insert_with(Vec::new)
            .extend(ud.leading_comments().clone());

        // 2) If exactly one final + trailing_comment => store that final normally plus record the trailing
        if finals.len() == 1 {
            let single_final = &finals[0];
            grouped_map
                .entry(key.clone())
                .or_insert_with(BTreeSet::new)
                .insert(single_final.clone());

            if let Some(tc) = ud.trailing_comment() {
                // store the trailing comment in trailing_comments keyed by (vis, prefix, single_final)
                let triple_key = (ud.visibility().clone(), prefix.clone(), single_final.clone());
                trailing_comments.insert(triple_key, tc.clone());
            }
        } else {
            // multiple finals or zero => no single-line trailing comment
            grouped_map
                .entry(key.clone())
                .or_insert_with(BTreeSet::new)
                .extend(finals);
        }
    }

    debug!(
        "group_and_sort_uses => grouped_map size={}, comment_map size={}, trailing_comments size={}",
        grouped_map.len(),
        comment_map.len(),
        trailing_comments.len()
    );
    info!("group_and_sort_uses => done");
    (grouped_map, comment_map, trailing_comments)
}


pub fn peek_next_non_whitespace(start: &Option<SyntaxElement>) -> Option<bool> {
    info!("peek_next_non_whitespace => start");
    trace!("Initial start={:?}", start);

    let mut cur = start.clone();
    while let Some(e) = cur {
        match e {
            NodeOrToken::Token(tok) if tok.kind() == SyntaxKind::WHITESPACE => {
                debug!("Skipping whitespace token => text len={}", tok.text().len());
                cur = tok.prev_sibling_or_token();
            }
            NodeOrToken::Token(tok) if tok.kind() == SyntaxKind::COMMENT => {
                trace!("Found comment token => returning Some(true)");
                info!("peek_next_non_whitespace => done => Some(true)");
                return Some(true);
            }
            NodeOrToken::Token(tok) => {
                debug!(
                    "Found non-comment token => kind={:?}, text={:?} => returning Some(false)",
                    tok.kind(),
                    tok.text()
                );
                info!("peek_next_non_whitespace => done => Some(false)");
                return Some(false);
            }
            NodeOrToken::Node(n) => {
                debug!(
                    "Found node => kind={:?} => returning Some(false)",
                    n.kind()
                );
                info!("peek_next_non_whitespace => done => Some(false)");
                return Some(false);
            }
        }
    }
    trace!("No more elements => returning None");
    info!("peek_next_non_whitespace => done => None");
    None
}


pub fn gather_use_items(file: &SourceFile, old_text: &str) -> Vec<UseItemInfo> {
    info!("Entering gather_use_items => file has {} items", file.items().count());
    let mut uses_data = Vec::new();

    for item in file.items() {
        // Only if it's a `use` item
        if let Some(u) = ast::Use::cast(item.syntax().clone()) {
            let rng = u.syntax().text_range();
            let start: usize = rng.start().into();
            let end:   usize = rng.end().into();

            let entire_range_text = &old_text[start..end];
            debug!("Found a `use` item at range {}..{}, raw_text:\n{}", start, end, entire_range_text);

            // Gather leading comments
            let leading_comments = gather_leading_comment_lines(u.syntax(), old_text);
            debug!("Leading comments => {:#?}", leading_comments);

            // We may detect a trailing same-line comment after the semicolon
            // (or after the block if there is no semicolon for some reason).
            let mut trailing_comment = None;
            if let Some((tc_text, tc_len)) = detect_trailing_comment_same_line(old_text, end) {
                debug!("Found trailing comment => {:?}, length={}", tc_text, tc_len);

                // Expand the range_end to cover the trailing comment
                // so we remove it from the old file in remove_old_use_statements
                let new_end = (end + tc_len).min(old_text.len());
                debug!("Expanded range_end from {} to {}", end, new_end);

                // We'll store that comment text in the struct
                trailing_comment = Some(tc_text);
                // Then we actually set `end` to the new_end for the final UseItemInfo
                // so that we don't leave the trailing comment behind in the old file
            }

            // Some AST fragments include leading comments in the same node text,
            // so remove exactly those leading comment bytes from `entire_range_text`.
            let leading_comment_bytes: usize = leading_comments.iter().map(|c| c.len()).sum();
            debug!("Truncating {} bytes of leading comment text from raw_text", leading_comment_bytes);

            let truncated_text = if leading_comment_bytes < entire_range_text.len() {
                &entire_range_text[leading_comment_bytes..]
            } else {
                ""
            };
            let truncated_text = truncated_text.trim_start();
            debug!("Truncated text for dissect:\n{}", truncated_text);

            // Attempt to dissect
            if let Some((vis, _use_kw, path_list)) = dissect_use_statement(truncated_text) {
                debug!("Dissect => visibility='{}', path_list='{}'", vis, path_list);

                let info = UseItemInfoBuilder::default()
                    .leading_comments(leading_comments)
                    .raw_text(entire_range_text.to_string())
                    .range_start(start)
                    // IMPORTANT: if we found a trailing comment, use that expanded new_end
                    .range_end(trailing_comment
                               .as_ref()
                               .map(|tc| end + tc.len())
                               .unwrap_or(end)
                               .min(old_text.len()))
                    .visibility(vis)
                    .path_list(path_list)
                    .trailing_comment(trailing_comment)
                    .build()
                    .unwrap();

                uses_data.push(info);
            } else {
                warn!("Failed to dissect => not recognized as a 'use' statement after truncation:\n{}", truncated_text);
            }
        } else {
            trace!("Item is not a `use` => ignoring");
        }
    }

    debug!("Exiting gather_use_items => returning {} items", uses_data.len());
    uses_data
}


pub fn split_path_into_prefix_and_final(full_path: &str) -> (String, Vec<String>) {
    info!(
        "split_path_into_prefix_and_final => entered with full_path={:?}",
        full_path
    );

    // If we detect something like "crate::foo::bar::{ ... }"
    if let Some(idx) = full_path.find("::{") {
        debug!("Detected braced path usage at index {}", idx);
        let prefix = &full_path[..idx];
        // The inside portion is whatever is between the '{' and the final '}' 
        // (assuming no trailing characters).
        let inside = &full_path[idx + 3..full_path.len() - 1];
        // Instead of a naive `.split(',')`, we do a shallow parse, 
        // respecting nested braces so that commas inside nested braces don't break us.
        let segments = split_braced_imports_top_level(inside);

        debug!(
            "Returning prefix={:?} with {} finals from braces",
            prefix,
            segments.len()
        );
        return (prefix.trim().to_string(), segments);
    } else {
        // No braced usage => fallback
        if let Some(idx2) = full_path.rfind("::") {
            debug!("Found last '::' at index {}", idx2);
            let prefix = &full_path[..idx2];
            let final_seg = &full_path[idx2 + 2..];
            let pr = prefix.trim().to_string();
            let fs = final_seg.trim().to_string();
            debug!("Returning prefix={:?}, single final={:?}", pr, fs);
            (pr, vec![fs])
        } else {
            debug!("No '::' found => entire input is final");
            ("".to_string(), vec![full_path.trim().to_string()])
        }
    }
}

impl SortAndFormatImports for CrateHandle {
    type Error = CrateError;
    async fn sort_and_format_imports(&self) -> Result<(), Self::Error> {
        let crate_path = self.as_ref();
        let imports_path = crate_path.join("src").join("imports.rs");

        // If imports_path doesn't exist => skip
        match tokio::fs::metadata(&imports_path).await {
            Ok(md) if md.is_file() => {
                // proceed
            }
            _ => {
                debug!("No src/imports.rs => skipping sort/format");
                return Ok(());
            }
        }

        debug!("Parsing and rewriting imports in {}", imports_path.display());

        // Read the file
        let mut file = File::open(&imports_path).await
            .map_err(|io_err| CrateError::IoError {
                io_error: Arc::new(io_err),
                context: format!("Opening {}", imports_path.display()),
            })?;

        let mut old_text = String::new();
        file.read_to_string(&mut old_text).await.map_err(|io_err| CrateError::IoError {
            io_error: Arc::new(io_err),
            context: format!("Reading {}", imports_path.display()),
        })?;

        // Transform
        let new_text = sort_and_format_imports_in_text(&old_text)
            .map_err(|e| {
                CrateError::SortAndFormatImportsInTextError {
                    message: format!("{:?}", e) // or however you want to represent it
                }
            })?;

        if new_text == old_text {
            debug!("No changes after sort/format => done");
            return Ok(());
        }

        // Rewrite
        let mut out_file = File::create(&imports_path).await.map_err(|io_err| CrateError::IoError {
            io_error: Arc::new(io_err),
            context: format!("Creating {}", imports_path.display()),
        })?;

        out_file.write_all(new_text.as_bytes()).await.map_err(|io_err| CrateError::IoError {
            io_error: Arc::new(io_err),
            context: format!("Writing {}", imports_path.display()),
        })?;

        info!("Finished sorting/formatting imports in {}", imports_path.display());
        Ok(())
    }
}

impl<P,H> SortAndFormatImports for Workspace<P,H> where for<'async_trait> P: From<PathBuf> + AsRef<std::path::Path> + Clone + Send + Sync + 'async_trait, H: CrateHandleInterface<P> + SortAndFormatImports<Error=CrateError> + Send + Sync {
    type Error = WorkspaceError;
    async fn sort_and_format_imports(&self) -> Result<(), Self::Error> {
        for crate_handle in self.into_iter() {
            let guard = crate_handle.lock().await;
            debug!("Sorting/formatting imports for crate: {}", guard.name());
            guard.sort_and_format_imports().await
                .map_err(|ce| WorkspaceError::CrateError(ce))?;
        }
        Ok(())
    }
}

