/// handle creating directories. That logic lives in `WorkspacerDir`.
#[derive(Debug, Clone, Builder, Getters, Setters, Serialize, Deserialize, Default)]
#[builder(setter(into), default)]
#[getset(get = "pub", set = "pub")]
