/// Represents the path to a `.ws` directory (local or global), along with
/// convenience methods for creating subdirectories or referencing the
/// `workspacer-config` file inside it.
///
/// This struct *differentiates* the notion of "the `.ws` directory" from "the config file."
/// It also allows you to do things like:
///  - Create `.ws/readme-writer-workspace`
///  - Create `.ws/test-upgrader-workspace`
///  - Clear or remove those subdirectories, etc.
#[derive(Debug, Clone)]
pub struct WorkspacerDir {
    root: PathBuf,
}

impl WorkspacerConfig {
    /// Tries to load the config from local `.ws`. If not found, tries global `.ws`.
    pub async fn load_with_fallback() -> Result<Option<WorkspacerConfig>, WorkspacerFallbackError> {
        let local_ws = WorkspacerDir::local();
        if let Some(cfg) = local_ws.load_config_async().await? {
            return Ok(Some(cfg));
        }
        // If local wasn't found, try global
        match WorkspacerDir::global() {
            Ok(global_ws) => {
                let global_cfg = global_ws.load_config_async().await?;
                Ok(global_cfg)
            }
            Err(e) => {
                warn!("Unable to find or create a global ws dir: {:?}", e);
                Ok(None)
            }
        }
    }
}

