    async fn create_new_crate_skeleton(&self, new_crate_name: &str) -> Result<P,WorkspaceError> {

        let crate_dir = self.as_ref().join(new_crate_name);
        info!("Creating new crate directory at {:?}", crate_dir);

        fs::create_dir_all(&crate_dir).await.map_err(|e| {
            WorkspaceError::IoError {
                io_error: Arc::new(e),
                context: format!("creating directory for new crate '{}'", new_crate_name),
            }
        })?;

        // Use `indoc!()` to keep the multi-line neat
        let cargo_toml_str = formatdoc! {r#"
            [package]
            name = "{new_crate_name}"
            version = "0.1.0"
            authors = ["YourName <you@example.com>"]
            license = "MIT"
            edition = "2024"
            description = "todo: write a description here"

            # keywords = []
            # categories = []

            [dependencies]
        "#};

        fs::write(crate_dir.join("Cargo.toml"), cargo_toml_str)
            .await
            .map_err(|e| WorkspaceError::IoError {
                io_error: Arc::new(e),
                context: format!("writing Cargo.toml for '{}'", new_crate_name),
            })?;

        // Create src dir
        let src_dir = crate_dir.join("src");
        fs::create_dir_all(&src_dir).await.map_err(|e| {
            WorkspaceError::IoError {
                io_error: Arc::new(e),
                context: format!("creating src dir for '{}'", new_crate_name),
            }
        })?;

        // We will not decide prefix logic here; we produce a placeholder imports
        let imports_path = src_dir.join("imports.rs");
        let placeholder_imports = indoc! {r#"
        // If we belong to a prefix group, we'd do `pub(crate) use prefix_3p::*;`
        // For now, placeholder comment.
        "#};

        fs::write(&imports_path, placeholder_imports).await
            .map_err(|e| WorkspaceError::IoError {
                io_error: Arc::new(e),
                context: format!("writing imports.rs for '{}'", new_crate_name),
            })?;

        // We do suffix derivation or skip it. For demonstration, let's do a naive approach:
        let suffix_snake = dash_to_snake_case(new_crate_name);
        let entrypoint_filename = format!("{}.rs", suffix_snake);
        let entrypoint_path = src_dir.join(&entrypoint_filename);
        let entrypoint_contents = indoc! {r#"
        crate::ix!();
        "#};
        fs::write(&entrypoint_path, entrypoint_contents)
            .await
            .map_err(|e| WorkspaceError::IoError {
                io_error: Arc::new(e),
                context: format!("writing entrypoint file '{}' for '{}'", entrypoint_filename, new_crate_name),
            })?;

        let lib_rs = formatdoc!{
            r#"
            #[macro_use] mod imports; use imports::*;

            x!{{{suffix_snake}}}
            "#
        };

        fs::write(src_dir.join("lib.rs"), lib_rs)
            .await
            .map_err(|e| WorkspaceError::IoError {
                io_error: Arc::new(e),
                context: format!("writing lib.rs for '{}'", new_crate_name),
            })?;

        // Optionally create a README
        // We skip here. Or we can do a minimal approach:
        let readme_path = crate_dir.join("README.md");
        if !readme_path.exists() {
            fs::write(&readme_path, format!("# {}\n\nTODO: fill description.\n", new_crate_name))
                .await
                .ok();
        }

        // Return the created path in your P
        Ok(P::from(crate_dir))
    }
}

impl<P,H> AddToWorkspaceMembers<P> for Workspace<P,H> where for<'async_trait> P: From<PathBuf> + AsRef<Path> + Send + Sync + Clone + 'static, H: CrateHandleInterface<P> + Send + Sync + 'static {
    async fn add_to_workspace_members(&self, new_crate_path: &P) -> Result<(), WorkspaceError> {
        info!("add_to_workspace_members - start for path='{}'", new_crate_path.as_ref().display());

        let top_cargo = self.as_ref().join("Cargo.toml");
        if !top_cargo.exists() {
            warn!("No top-level Cargo.toml found => skipping workspace membership update");
            return Ok(());
        }

        let contents = fs::read_to_string(&top_cargo).await.map_err(|e| {
            WorkspaceError::IoError {
                io_error: Arc::new(e),
                context: "reading top-level Cargo.toml".into()
            }
        })?;

        let mut doc = contents.parse::<TomlEditDocument>().map_err(|toml_err| {
            CargoTomlError::TomlEditError {
                cargo_toml_file: top_cargo.clone(),
                toml_parse_error: toml_err,
            }
        })?;

        // Check if we even have [workspace]
        let Some(workspace_item) = doc.get_mut("workspace") else {
            warn!("top-level Cargo.toml lacks [workspace]; skipping membership update");
            return Ok(());
        };

        // Ensure "workspace" is actually a table
        let Some(workspace_table) = workspace_item.as_table_mut() else {
            warn!("top-level Cargo.toml has 'workspace' but not a table; skipping membership update");
            return Ok(());
        };

        // Now ensure [workspace].members exists and is an array
        if workspace_table.get("members").is_none() {
            debug!("No 'members' found under [workspace], creating a fresh array");
            workspace_table.insert("members", TomlEditItem::Value(TomlEditValue::Array(TomlEditArray::new())));
        }

        let Some(members_item) = workspace_table.get_mut("members") else {
            // Should never happen if we just inserted it
            warn!("Failed to retrieve or create [workspace].members - skipping");
            return Ok(());
        };

        let Some(members_arr) = members_item.as_array_mut() else {
            // If it's not an array, we error
            return Err(WorkspaceError::InvalidCargoToml(
                CargoTomlError::CargoTomlWriteError(
                    CargoTomlWriteError::WriteWorkspaceMember {
                        io: Arc::new(std::io::Error::new(
                            std::io::ErrorKind::Other,
                            "[workspace].members is not an array"
                        ))
                    }
                )
            ));
        };

        // Compute a relative path from workspace root to new_crate_path
        let rel_path = new_crate_path.as_ref()
            .strip_prefix(self.as_ref())
            .unwrap_or(new_crate_path.as_ref())
            .to_string_lossy()
            .replace("\\", "/"); // for Windows

        // If not already in the array, push it
        let already_present = members_arr.iter().any(|itm| itm.as_str() == Some(&rel_path));
        if already_present {
            debug!("New crate path='{}' already in [workspace].members => skipping", rel_path);
        } else {
            debug!("Appending '{}' to [workspace].members array", rel_path);
            members_arr.push(&rel_path);
            let updated = doc.to_string();
            fs::write(&top_cargo, updated).await.map_err(|e| {
                WorkspaceError::IoError {
                    io_error: Arc::new(e),
                    context: format!("writing top-level Cargo.toml after adding member={}", rel_path)
                }
            })?;
        }

        info!("Successfully updated workspace members with '{}'", rel_path);
        Ok(())
    }
}

